'use strict';

// Somnus Domina — Zagalhta's Exolunar Collection / Capítulo 7 — Magias.
// As versões Legacy/revisadas são mantidas separadas das versões oficiais.
// Pele de Dragão é uma reimpressão mecanicamente equivalente à entrada de Lyre e recebe apenas procedência adicional.
window.GRIMORIO_ZAGALHTA_SPELLS = [{"id":"zagalhta-antigravity-zone","name":"Zona Antigravidade","originalName":"Antigravity Zone","aliases":[],"level":1,"school":"Transmutação","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Bardo, Inscritor, Cavaleiro das Pétalas, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Escolha um ponto que você possa ver dentro do alcance. A partir desse ponto, expande-se uma esfera de 4,5 metros de raio que permanece durante a duração da magia. A área dentro dessa esfera é tratada como um ambiente de gravidade zero ou de baixa gravidade (à sua escolha ao conjurar a magia).","higher":"Quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O raio da esfera dobra.\n• A duração da magia aumenta, na ordem: 1 hora, 10 horas, 1 dia, 30 dias, 1 ano, permanente.\n• A magia deixa de exigir concentração, e você pode encerrá-la a qualquer momento como uma ação.\n• Você pode escolher um ponto adicional dentro do alcance para criar uma bolha antigravidade adicional, da qual surge outra esfera. Cada vez que escolher este efeito, o raio de cada esfera individual é reduzido à metade, arredondado para cima para o incremento de 3 metros mais próximo.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":187,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Esta versão apresenta diferenças mecânicas em relação à versão de Lyre e, por isso, permanece como entrada própria."},{"id":"zagalhta-astral-collision","name":"Colisão Astral","originalName":"Astral Collision","aliases":[],"level":1,"school":"Conjuração","time":"1 ação bônus","range":"12 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Alma Favorecida, Paladino, Cavaleiro das Pétalas, Patrulheiro, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Escolha uma criatura que você possa ver dentro do alcance da magia. Você se transforma em um feixe de luz que atravessa o espaço em direção a ela e, como parte da magia, ataca o alvo com uma arma que esteja portando, realizando um ataque corpo a corpo com magia ou um ataque corpo a corpo com arma (à sua escolha). Em um acerto, você causa o dano da arma mais 1d8 de dano radiante. Em seguida, você termina a magia em um espaço desocupado adjacente ao alvo, que deve estar o mais próximo possível do espaço de onde você partiu.\n\nBônus de Astromancia. Se conjurar esta magia em um ambiente de gravidade zero, o alcance da magia é triplicado.","higher":"Quando você conjura esta magia usando um espaço de 2º nível ou superior, ela recebe um dos efeitos a seguir, à sua escolha, para cada nível do espaço acima do 1º:\n• O dano radiante da magia aumenta em 1d8.\n• O alcance da magia aumenta em 6 metros.\n• (2 níveis) Você pode escolher um alvo adicional dentro do alcance da magia a partir do alvo anterior. Depois que o ataque contra o alvo anterior for resolvido, você atravessa o espaço até o novo alvo e realiza outro ataque conforme descrito. Você termina a magia em um espaço adjacente ao último alvo. Você deve ser capaz de ver cada alvo no momento da conjuração.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":187,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-astral-fissure","name":"Fissura Astral","originalName":"Astral Fissure","aliases":[],"level":9,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (uma pérola negra no valor de pelo menos 1.000 po, consumida pela magia)","material":"uma pérola negra no valor de pelo menos 1.000 po, consumida pela magia","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Escolha um ponto que você possa ver dentro do alcance da magia. Um portal deliberadamente instável aparece ali e colapsa sobre si mesmo, obrigando cada criatura em uma esfera de 9 metros de raio centrada nesse ponto a realizar um teste de resistência de Destreza. Em caso de falha, a criatura sofre 10d12 de dano contundente e 10d12 de dano de energia e é puxada para dentro da fissura astral resultante, onde permanece durante a duração da magia, perdida entre planos. Em caso de sucesso, sofre metade do dano e não é puxada.\n\nUma criatura que comece o turno dentro da fissura sofre 3d12 de dano psíquico devido ao vazio em que se encontra e fica incapacitada até o início do próximo turno. Ao fim do turno, ela realiza um teste de resistência de Carisma; em caso de sucesso, força seu caminho de volta pelo espaço e reaparece em um espaço desocupado o mais próximo possível de onde desapareceu, encerrando os efeitos da magia sobre ela. Se você perder a concentração na magia sem usar uma ação bônus conforme descrito abaixo, todas as criaturas puxadas para dentro da fissura reaparecem.\n\nDurante a duração da magia, você pode usar uma ação bônus para encerrar os efeitos sobre quaisquer criaturas na fissura à sua escolha. Ao fazer isso, pode fazê-las reaparecer em qualquer espaço desocupado que escolher a até três vezes o alcance da magia.\n\nBônus de Astromancia. Se conjurar esta magia em um ambiente de gravidade zero, o limite de tamanho descrito abaixo é dobrado: apenas criaturas mais de quatro categorias de tamanho maiores que você deixam de ser puxadas. O alcance da magia também dobra.\n\nLimite de Tamanho. Criaturas mais de duas categorias de tamanho maiores que você não são puxadas para dentro da fissura em caso de falha, mas ainda sofrem o dano e ficam atordoadas até o fim do próximo turno.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":188,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-astral-weapon","name":"Arma Astral","originalName":"Astral Weapon","aliases":[],"level":3,"school":"Evocação","time":"1 ação","range":"Pessoal (12 metros)","comp":"V, S, M (um fragmento de rocha ou detrito espacial moldado como uma pequena lâmina, no valor de pelo menos 100 po)","material":"um fragmento de rocha ou detrito espacial moldado como uma pequena lâmina, no valor de pelo menos 100 po","duration":"1 minuto","classes":"Clérigo, Inscritor, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você une energia radiante, poeira estelar e matéria escura para criar um constructo de luz estelar em forma de arma, que flutua próximo a você. Ela pode ser usada para realizar as ações abaixo, mas não pode executar mais de um tipo delas no mesmo turno, embora um mesmo tipo possa ser usado várias vezes quando permitido:\n• Como uma ação, e também uma vez ao conjurar a magia, realize dois ataques contra uma criatura dentro do alcance da magia.\n• Como uma ação bônus, realize um ataque com a arma contra uma criatura dentro do alcance da magia.\n• Como uma reação ao ser atingido por um ataque originado de dentro do alcance da magia, realize um ataque com a arma contra a criatura atacante.\n\nQuando você ataca uma criatura com a arma, todos os ataques subsequentes que fizer com ela naquele turno devem ter o mesmo alvo. Se o alvo estiver a até 1,5 metro de você, o ataque é corpo a corpo com magia; além disso, é um ataque à distância com magia. Em um acerto, a arma causa 2d8 de dano radiante + seu modificador de habilidade de conjuração ou de Força, à sua escolha.\n\nBônus de Astromancia. Ao usar esta arma em um ambiente de gravidade zero, o alcance da magia é triplicado.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 3º:\n• O alcance da magia dobra.\n• A arma obtém um acerto crítico com resultado 19 no d20 (2 níveis), 18 (3 níveis) ou 17 (4 níveis).\n• (2 níveis) O dano radiante da arma aumenta em 1d8.\n• (3 níveis) Quando usar sua ação ou ação bônus para atacar com a arma, ela pode realizar um ataque adicional.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":188,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-aurashroud","name":"Manto Áurico","originalName":"Aurashroud","aliases":[],"level":3,"school":"Abjuração","time":"1 ação","range":"Pessoal (18 metros)","comp":"S","material":"","duration":"1 minuto","classes":"Alma Favorecida, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Energias primordiais giram ao seu redor, protegendo e imbuindo você e cada ação que realiza. Durante a duração da magia, você recebe os benefícios a seguir:\n• Você ganha um Limiar de Dano igual a 5 + duas vezes o nível em que a magia foi conjurada.\n• Seus ataques e o dano causado por eles são considerados eidólicos e mágicos.\n• Efeitos prejudiciais que levem tamanho em consideração tratam você como sendo, no mínimo, de tamanho Tremendo. Seu tamanho real não muda. Você pode empurrar e agarrar criaturas como se fosse Tremendo.\n• Seus ataques com arma causam um dado adicional de dano da arma.\n• Quando falhar em um teste de resistência, você pode usar sua reação para obter sucesso em vez disso. Se fizer isso, realize um teste de Queima de Eidomancia como se a magia tivesse terminado. Se falhar, a magia termina e você falha automaticamente no teste de Queima de Eidomancia decorrente desse término.\n\nAlém disso, você pode usar sua ação bônus para conjurar e arremessar uma rajada de energia contra uma criatura dentro do alcance da magia como um ataque à distância com magia, causando dano contundente igual a 1d10 × o nível em que a magia foi conjurada.\n\nVocê pode encerrar este efeito a qualquer momento como uma ação bônus ou ação. Se encerrá-lo como uma ação, tem vantagem no teste de Queima de Eidomancia.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, ela é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode causar o tipo de dano da sua Encarnação no lugar do dano contundente desta magia.\n\nQueima de Eidomancia. CD 10 + nível da magia + número de seus turnos encerrados desde a conjuração; 3 níveis de exaustão em caso de falha; a magia fica indisponível por 7 dias.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 3º:\n• O alcance de 18 metros da magia dobra.\n• Seus ataques com arma causam um dado adicional de dano.\n• A CD da Queima de Eidomancia desta magia é reduzida em 3.\n• (3 níveis) Seus ataques com arma são considerados capazes de causar Dano Macro contra criaturas Grandes ou menores; contra elas, você obtém o resultado máximo nos dados de dano da arma que rolar.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":188,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma","Eidomancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-auto-repair","name":"Autorreparo","originalName":"Auto-Repair","aliases":[],"level":5,"school":"Transmutação","time":"1 ação","range":"Toque","comp":"V, S, M (platina no valor de 10 po por nível em que a magia é conjurada, consumida pela magia)","material":"platina no valor de 10 po por nível em que a magia é conjurada, consumida pela magia","duration":"Concentração, até 1 minuto","classes":"Bardo, Inscritor, Patrulheiro","ritual":false,"concentration":true,"desc":"Você toca um constructo e o impregna de magia restauradora. Ele recupera imediatamente 5d10 + 10 pontos de vida. Depois disso, durante a duração da magia, recupera no início de cada um de seus turnos uma quantidade de pontos de vida igual a duas vezes o nível em que esta magia foi conjurada. Se a criatura for reduzida a 0 pontos de vida durante esse período, no início do próximo turno ela recupera imediatamente uma quantidade de pontos de vida igual ao nível em que a magia foi conjurada multiplicado pelo número de turnos restantes de duração da magia, deixa imediatamente de estar morrendo e a magia termina.\n\nEnquanto a magia estiver ativa, a criatura-alvo pode escolher encerrar seus efeitos como uma reação para obter sucesso em um teste de resistência de Força ou Constituição no qual tenha falhado.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":189,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-blasting-tail","name":"Cauda Explosiva","originalName":"Blasting Tail","aliases":[],"level":3,"school":"Conjuração","time":"1 ação","range":"3 metros","comp":"S","material":"","duration":"Instantânea","classes":"Druida, Inscritor, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você conjura uma cauda que varre a área ao seu redor, atingindo cada criatura que escolher a até 3 metros. Cada alvo deve realizar um teste de resistência de Força. Em caso de falha, sofre 4d10 de dano contundente e é empurrado 1,5 metro para trás, uma distância igual à metade do alcance da magia. Qualquer criatura que falhe encerra imediatamente quaisquer agarrões que tenha iniciado.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, ela é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode adicionar um dado de dano da sua Encarnação ao dano desta magia.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 3º:\n• O alcance da magia dobra.\n• O dano da magia aumenta em 1d10.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":189,"category":"Zagalhta's Exolunar Collection","traits":["Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-bright-arrow","name":"Flecha Luminosa","originalName":"Bright Arrow","aliases":[],"level":0,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"S","material":"","duration":"Instantânea","classes":"Clérigo, Feiticeiro","ritual":false,"concentration":false,"desc":"Você cria brevemente um arco e uma flecha de poder radiante e dispara contra um alvo dentro do alcance como um ataque à distância com magia. Em um acerto, o alvo sofre 1d10 de dano radiante. Se algum dado de dano desta magia obtiver resultado 10 ou se você conseguir um acerto crítico, o alvo fica cego até o fim do próximo turno dele.\n\nAprimoramento de Truque. Esta magia causa 1d10 de dano radiante adicional quando você alcança cada um dos seguintes níveis: 5º nível (2d10), 11º nível (3d10) e 17º nível (4d10).","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":189,"category":"Zagalhta's Exolunar Collection","traits":[],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-conjure-frame-echo","name":"Conjurar Eco de Frame","originalName":"Conjure Frame Echo","aliases":[],"level":5,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (um objeto retirado do corpo de uma unidade frame ou um componente de uma no valor de pelo menos 500 po)","material":"um objeto retirado do corpo de uma unidade frame ou um componente de uma no valor de pelo menos 500 po","duration":"Concentração, até 1 hora","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você invoca um eco mecânico de uma unidade frame na forma de um DGR ou de um frame lunar. Esse constructo artificial surge em um espaço desocupado que você possa ver a até 18 metros, ou você pode conjurá-lo em um espaço sobreposto ao seu para embarcar automaticamente na unidade. A unidade usa o bloco de estatísticas Eco de Unidade Frame, com características determinadas por ter sido conjurada como DGR ou frame lunar. O eco desaparece quando cai a 0 pontos de vida ou quando a magia termina.\n\nA unidade frame é aliada sua e de seus companheiros. Em combate, compartilha sua contagem de iniciativa, mas realiza o turno imediatamente depois do seu. Ela obedece aos seus comandos verbais, sem exigir ação sua; se você não der nenhum comando, usa a ação Esquivar e seu deslocamento para evitar perigo.\n\nNotas do Eco de Frame. Classe de Armadura: 14 + o nível em que a magia foi conjurada. Pontos de Vida: 10 × o nível em que a magia foi conjurada. Dados de Vida: uma quantidade de dados igual ao nível da magia; d10 enquanto Enorme e d12 enquanto Imenso ou Tremendo. Limiar de Dano: 5 + o nível da magia. Idiomas: entende os idiomas conhecidos pelo conjurador, mas não fala. Multiataque: realiza uma quantidade de ataques com arma igual à metade do nível em que a magia foi conjurada. Tamanho: Enorme; aumenta uma categoria quando conjurada no 7º nível (Imenso) e novamente no 9º nível (Tremendo).\n\nEco de Unidade Frame — constructo Enorme (DGR ou frame lunar). CA 14 + nível da magia; PV 10 × nível da magia; Limiar 5 + nível da magia. Deslocamentos: 9 m, voo (pairar) 18 m, aceleração 0-G 36 m. For 20 (+5), Des 12 (+1), Con 16 (+3), Int 10 (+0), Sab 18 (+4), Car 10 (+0). Imunidades: necrótico e veneno (DGR); dano contundente, perfurante e cortante de ataques não mágicos (frame lunar); às condições enfeitiçado, exausto, amedrontado, envenenado e inconsciente. Sentidos: percepção às cegas 18 m, Percepção passiva 14.\n\nCaracterísticas. Imutável. Liga Metálica (somente DGR): o constructo é resistente a dano causado por criaturas duas ou mais categorias de tamanho menores que ele. Resistência à Magia (somente frame lunar): tem vantagem em testes de resistência contra efeitos mágicos. Pilotagem: o conjurador pode gastar 1,5 m de movimento para entrar no eco como se o pilotasse. Enquanto o faz, possui cobertura total, pode realizar suas ações por meio do corpo da unidade e enxergar através dos sentidos dela; porém, sempre que o eco sofre dano, realiza um teste de concentração como se você tivesse sofrido esse dano.\n\nAções. Multiataque: a unidade realiza uma quantidade de ataques igual à metade do nível do espaço usado para invocá-la e, em seguida, usa Lâmina de Aura ou Barragem de Mísseis. Golpe de Frame: ataque corpo a corpo com arma usando seu modificador de ataque com magia, alcance 3 m, um alvo; em um acerto, causa 1d10 + 5 + nível da magia de dano perfurante ou contundente. Lâmina de Aura (somente frame lunar): atinge cada alvo escolhido dentro de uma distância igual a 1,5 m × o nível da magia; cada alvo realiza um teste de resistência de Destreza contra sua CD de magia, sofrendo 2d8 de dano radiante em caso de falha. Barragem de Mísseis (somente DGR): dispara contra uma quantidade de alvos igual à metade do nível da magia, arredondada para cima, a até 36 m; cada alvo realiza um teste de resistência de Destreza contra sua CD de magia, sofrendo 3d6 de dano de energia em caso de falha. Impulso Mach (somente DGR): o deslocamento do eco dobra até o fim do turno e ele usa a ação Disparada. Teleporte (somente frame lunar): o eco se teleporta, junto do piloto e do que estiver carregando, para um espaço desocupado que possa ver a até 24 m.","higher":"Quando você conjura esta magia usando um espaço de 6º nível ou superior, as estatísticas da unidade frame mudam conforme descrito no bloco de estatísticas.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":189,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-cure-wounds","name":"Curar Ferimentos","originalName":"Cure Wounds","aliases":[],"level":1,"school":"Evocação","time":"1 ação","range":"Toque","comp":"V, S","material":"","duration":"Instantânea","classes":"Bardo, Clérigo, Druida, Paladino, Patrulheiro","ritual":false,"concentration":false,"desc":"Uma criatura que você toca recupera pontos de vida iguais a 2d8 + seu modificador de habilidade de conjuração. Esta magia não surte efeito em mortos-vivos ou constructos.\n\nBenção do Curandeiro. Quando esta magia é conjurada por um Clérigo ou Druida, seus d8 se tornam d10.","higher":"Quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 1º:\n• A cura da magia aumenta em 2d8.\n• O alvo se recupera de toda Fadiga de Combate que esteja sofrendo.\n• Você pode conjurar esta magia à distância em vez de por toque: até 3 m (1 nível), 9 m (2 níveis), 18 m (3 níveis) ou 36 m (4 níveis).","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":191,"category":"Zagalhta's Exolunar Collection","traits":["Legado 5.19"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. A fonte classifica esta entrada como uma magia Legacy/revisada; ela foi mantida separada da versão oficial do D&D 5e para preservar as diferenças mecânicas."},{"id":"zagalhta-dead-light","name":"Luz Morta","originalName":"Dead Light","aliases":[],"level":4,"school":"Ilusão","time":"1 ação","range":"18 metros (esfera de 9 metros de raio)","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você cria uma fonte de luz fantasmagórica centrada em um ponto que escolher a até 18 metros, formando uma esfera de 9 metros de raio. Quando uma criatura começa o turno dentro dela ou entra na luz pela primeira vez no turno, fica presa na ilusão e deve realizar um teste de resistência de Sabedoria. Em caso de falha, fica cega até o início do próximo turno, mesmo se normalmente for imune à condição ou possuir percepção às cegas, a menos que seja inteiramente imune a ilusões. Ao falhar, também cambaleia 3 metros em uma direção determinada aleatoriamente, provocando ataques de oportunidade normalmente.\n\nPara determinar a direção, role 1d12. Com resultado 1–5, a criatura cambaleia em direção ao centro do efeito. Com 6 ou mais, move-se em outra direção, avançando no sentido horário: por exemplo, se 1–5 indicar norte, 6 indica nordeste, 7 leste e assim por diante. Se colidir com outra criatura ou um objeto sólido e intransponível, para imediatamente.\n\nAtaques feitos de fora contra qualquer coisa dentro da esfera distorcida de luz são realizados como se o atacante estivesse cego, a menos que ele consiga enxergar através de ilusões.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível.","higher":"Quando você conjura esta magia no 5º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• Criaturas que falharem no teste sofrem 2d8 de dano psíquico; você pode usar o tipo de dano da sua Encarnação no lugar de psíquico.\n• O alcance da magia aumenta em 9 metros e o raio da esfera aumenta em 4,5 metros.\n• Escolha duas criaturas, podendo escolher a si mesmo. Elas são completamente ignoradas pelos efeitos da magia e percebem apenas um brilho inofensivo.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":191,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-dead-nova","name":"Nova Morta","originalName":"Dead Nova","aliases":[],"level":5,"school":"Evocação","time":"1 ação","range":"36 metros (raio de 12 metros)","comp":"V, S","material":"","duration":"Instantânea","classes":"Clérigo, Alma Favorecida, Paladino, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você cria uma explosão de energia centrada em um ponto que possa ver a até 36 metros. O poder de um sol moribundo irrompe em uma esfera de 12 metros de raio. Cada criatura na esfera deve realizar um teste de resistência de Destreza. Em caso de falha, sofre 6d10 de dano radiante e 6d10 de dano necrótico. Uma criatura que falhe por 5 ou mais também fica lenta até o início do seu próximo turno.\n\nBônus de Astromancia. Se conjurar esta magia em um ambiente de gravidade zero, criaturas que falharem por 5 ou mais ficam atordoadas em vez de lentas.\n\nQueima de Eidomancia. CD 10 + nível da magia; 2 níveis de exaustão em caso de falha; a magia fica indisponível por 7 dias.","higher":"Quando você conjura esta magia no 6º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 5º:\n• O alcance aumenta em 18 metros e o raio da esfera aumenta em 6 metros.\n• Os danos radiante e necrótico aumentam, cada um, em 2d6.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":191,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia","Eidomancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-deathgate","name":"Portal da Morte","originalName":"Deathgate","aliases":[],"level":5,"school":"Necromancia","time":"1 ação","range":"18 metros (hemisfério de 9 metros de raio)","comp":"S","material":"","duration":"Concentração, até 10 minutos","classes":"Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Um portal de escuridão surge de um ponto que você escolher a até 18 metros. Esse portal para um semiplano sombrio e insidioso abre-se apenas de um lado, escolhido no momento da conjuração. Cada criatura em uma hemisfera de 9 metros de raio centrada no lado aberto deve realizar um teste de resistência de Força. Em caso de falha, é puxada para dentro do portal e fica aprisionada em um semiplano de morte durante a duração da magia. Em caso de sucesso, torna-se imune a esta instância da magia. O portal só pode puxar criaturas até três categorias de tamanho maiores que você. Quando a magia termina, as criaturas são ejetadas para espaços desocupados próximos ao portal, à sua escolha.\n\nCriaturas Aprisionadas. Uma criatura presa no Portal da Morte fica incapacitada, não pode se mover e não percebe acontecimentos externos. As criaturas aprisionadas conseguem perceber e falar umas com as outras, mas não conseguem interagir de outras formas. Ao terminar um turno dentro do portal, a criatura realiza um teste de resistência de Carisma. Em caso de falha, sofre 4d8 de dano necrótico, e metade desse dano também reduz seu máximo de pontos de vida. Em caso de sucesso, não sofre dano e é libertada imediatamente, surgindo no espaço desocupado mais próximo do portal.\n\nContato Perigoso. Uma criatura que ainda não tenha sido aprisionada e faça contato físico com o portal deve realizar o teste de resistência de Força contra seu efeito principal, sendo puxada em caso de falha.\n\nRecuperação ou Aprisionamento. Nos turnos posteriores à conjuração, você pode usar sua ação para escolher uma criatura a até 18 metros do portal e tentar puxá-la para dentro, forçando-a a realizar o teste de resistência de Força. Também pode usar sua ação para libertar qualquer quantidade de criaturas presas, como se elas tivessem obtido sucesso no teste.\n\nSelo Final. Como uma ação, você pode encerrar a magia antecipadamente e obrigar todas as criaturas aprisionadas a realizar um teste de resistência de Constituição. Em caso de falha, sofrem 4d8 de dano necrótico e 4d8 de dano de energia e são ejetadas. Se encerrar a magia dessa forma, a CD da Queima de Eidomancia diminui em 5, até o mínimo de 15.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode substituir o dano de energia pelo tipo de dano da sua Encarnação.\n\nQueima de Eidomancia. CD 10 + nível da magia + número de turnos desde que foi conjurada; 3 níveis de exaustão em caso de falha; a magia fica indisponível por 7 dias.","higher":"Quando você conjura esta magia no 6º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 5º:\n• O alcance aumenta em 9 metros.\n• O portal pode aprisionar criaturas duas categorias de tamanho adicionais maiores que você.\n• Os danos necrótico e de energia aumentam, cada um, em 1d8.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":191,"category":"Zagalhta's Exolunar Collection","traits":["Eidomancia","Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-designate-constructs","name":"Designar Constructos","originalName":"Designate Constructs","aliases":[],"level":1,"school":"Encantamento","time":"Especial","range":"Especial","comp":"V","material":"","duration":"Especial","classes":"Bardo, Clérigo, Druida, Inscritor, Patrulheiro","ritual":false,"concentration":false,"desc":"Quando você conjura uma magia de duração instantânea que exclui constructos de seus efeitos, pode conjurar Designar Constructos ao mesmo tempo, ignorando as restrições normais para conjurar várias magias, como parte da mesma ação. Essa instância da magia passa a ter como alvos especificamente constructos e exclui todos os demais tipos de criatura.\n\nIsso não se aplica a magias que especificam quais tipos de criatura podem ser alvos e excluem amplamente todos os demais. Designar Constructos altera apenas magias cujo texto exclui constructos, como Curar Ferimentos.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":192,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-diamond-air","name":"Ar Diamantino","originalName":"Diamond Air","aliases":[],"level":9,"school":"Abjuração","time":"1 ação","range":"Pessoal (esfera de 90 metros de raio)","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"O ar em uma esfera de 90 metros de raio centrada em você enche-se subitamente de fragmentos cristalinos que distorcem gravidade e massa. A área torna-se um ambiente de gravidade zero, e você recebe nela um deslocamento de aceleração 0-G igual ao dobro do seu deslocamento base, ou ao dobro de qualquer deslocamento de voo que possua.\n\nContenção. Quando uma criatura dentro da área tenta sair dela, deve realizar um teste de resistência de Força. Em caso de falha, seu deslocamento é reduzido a 0 até o início do próximo turno.\n\nTempestade de Diamantes. Uma vez ao conjurar a magia, e depois como uma ação nos turnos seguintes, escolha um ponto na área. Os fragmentos se agitam em um cubo de 6 metros centrado ali. Cada criatura no cubo realiza um teste de resistência de Destreza, sofrendo 3d10 de dano cortante e 2d10 de dano de energia em caso de falha, ou metade em caso de sucesso.\n\nManipular Gravidade. Uma vez ao conjurar a magia e depois como uma ação bônus nos turnos seguintes, escolha uma criatura na área e manipule a gravidade ao redor dela. O alvo realiza um teste de resistência de Força. Em caso de falha, você pode movê-lo para um espaço à sua escolha a até 18 metros e reduzir o deslocamento dele a 0 até o início do seu próximo turno.\n\nManto Protetor. Enquanto estiver na área afetada, todo dano que você sofre é reduzido em 10.\n\nZona Cortante. Sempre que uma criatura começar o turno na área ou entrar nela pela primeira vez no turno, deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 2d6 de dano cortante. Quando uma criatura falhar, você pode escolher fazê-la obter sucesso em vez disso.\n\nBônus de Astromancia. Se conjurar esta magia em um ambiente de gravidade zero, seu alcance dobra.\n\nBônus do Cavaleiro Dracônico. Se esta magia for conjurada por um Cavaleiro Dracônico, ele pode usar a ação Tempestade de Diamantes como se fosse uma magia com tempo de conjuração de 1 ação, permitindo substituir um ataque por ela através de Ação Encadeada. O dano cortante pode ser substituído pelo tipo de dano da Encarnação.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":192,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia","Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-dragon-strike","name":"Golpe do Dragão","originalName":"Dragon Strike","aliases":[],"level":3,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Instantânea","classes":"Feiticeiro, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você conjura a garra fantasmagórica de um dragão para atingir um alvo que possa ver a até 9 metros, realizando um ataque corpo a corpo com magia. Em um acerto, o alvo sofre 6d8 de dano contundente e é empurrado 4,5 metros, metade do alcance da magia, em qualquer direção à sua escolha. Depois, deve realizar um teste de resistência de Força, ficando caído em caso de falha. Se o alvo for mais de duas categorias de tamanho maior que você, é empurrado apenas metade dessa distância e tem vantagem no teste de resistência de Força.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode substituir o dano contundente pelo tipo de dano da sua Encarnação.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 3º:\n• O alcance aumenta em 9 metros.\n• A magia causa 1d8 adicional de dano.\n• Você pode escolher um alvo adicional dentro do alcance, realizando um ataque corpo a corpo com magia separado contra ele.\n• O limite de categorias de tamanho considerado pela magia aumenta em duas.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":192,"category":"Zagalhta's Exolunar Collection","traits":["Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-volcora-s-empowered-familiar","name":"Familiar Fortalecido de Volcora","originalName":"(Volcora’s) Empowered Familiar","aliases":["Empowered Familiar","Volcora’s Empowered Familiar"],"level":3,"school":"Transmutação","time":"1 ação","range":"18 metros","comp":"V, S, M (uma figura de argila representando a forma fortalecida pretendida para o familiar)","material":"uma figura de argila representando a forma fortalecida pretendida para o familiar","duration":"Concentração, até 10 minutos","classes":"Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você desperta um poder maior em um familiar a até 18 metros. Ele deve ter sido conjurado por você ou por um aliado presente que permita o efeito. O familiar mantém suas estatísticas existentes e recebe as alterações a seguir:\n• +3 de bônus na Classe de Armadura.\n• Seu tamanho torna-se Médio ou aumenta em uma categoria, o que resultar no maior tamanho.\n• Quando usa a ação Atacar, emprega seu modificador de habilidade de conjuração no lugar do modificador normal de ataque e dano.\n• Ganha um ataque natural com alcance de 1,5 m; esse ataque e seus ataques existentes causam 3d8 de um tipo de dano apropriado à forma do familiar.\n• Seus ataques são mágicos.\n• Seu máximo de pontos de vida aumenta em 10 × o nível da magia.\n• Ganha resistência a um tipo de dano ao qual você seja resistente ou, conforme seu tipo, radiante (celestial), psíquico (fada) ou fogo (corruptor).","higher":"Quando esta magia é conjurada no 5º nível ou superior, o familiar pode usar Multiataque, realizando dois ataques no 5º nível, três no 7º ou quatro no 9º.\n\nAlém disso, quando conjurada no 4º nível ou superior, escolha um dos efeitos abaixo para cada nível do espaço acima do 3º:\n• Você pode conjurar a magia como uma ação bônus.\n• A CA do familiar aumenta em 1.\n• O familiar recebe +1 em testes de resistência e testes de atributo.\n• O familiar recebe +1 em jogadas de ataque e dano.\n• (2 níveis) O tamanho do familiar aumenta em mais uma categoria e seu alcance passa a 3 m.\n• (2 níveis) Os ataques do familiar causam 1d8 adicional de dano.\n• (2 níveis) O familiar tem vantagem em testes de resistência contra efeitos mágicos e, quando obtém sucesso em um teste contra um deles, não sofre dano desse efeito.\n• (3 níveis) O familiar ganha resistência a dano perfurante, cortante ou contundente, à sua escolha.\n• (3 níveis) A magia deixa de exigir concentração; você pode encerrá-la como uma ação bônus.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":193,"category":"Zagalhta's Exolunar Collection","traits":[],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-extinction","name":"Extinção","originalName":"Extinction","aliases":[],"level":9,"school":"Evocação","time":"1 minuto","range":"Visão (raio de 8 km)","comp":"V, S, M (uma esfera de cristal no valor de pelo menos 10.000 po, consumida pela magia)","material":"uma esfera de cristal no valor de pelo menos 10.000 po, consumida pela magia","duration":"10 minutos","classes":"Bruxo, Mago, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você faz um evento cataclísmico ser sonhado para a realidade, rasgando o céu cerca de 8 quilômetros acima do ponto escolhido e produzindo uma ameaça cósmica — como um meteoro do tamanho de uma cidade, uma perturbação gravitacional ou outro instrumento de destruição absoluta. Durante 10 minutos, tudo em uma esfera de aproximadamente 8 quilômetros de raio centrada no ponto fica sujeito aos efeitos abaixo.\n\nArauto do Fim. Como uma ação bônus, escolha um ponto que possa ver dentro da área. Cada criatura em uma esfera de 6 metros de raio centrada nesse ponto sofre os efeitos de Atmosfera Perigosa abaixo, atingida por uma concentração dos fenômenos devastadores. Enquanto você estiver dentro da área, recebe deslocamento de aceleração 0-G igual ao seu deslocamento base e ignora os efeitos da exaustão.\n\nAtmosfera Perigosa. Uma criatura exposta ao ambiente aberto, sem cobertura, por mais de 1 minuto deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 5d10 de dano de energia e 1 ponto de Fadiga de Combate. Independentemente do resultado, repete o teste ao fim de cada minuto adicional de exposição. Você é imune a este efeito.\n\nDistorção Gravitacional. A área da magia é considerada um ambiente de baixa gravidade durante sua duração.\n\nObliteração. Se a duração terminar sem a magia ter sido encerrada antecipadamente, o cataclismo se resolve. Cada criatura na área realiza um teste de resistência de Constituição, sofrendo 20d10 de dano de energia em caso de falha ou metade em caso de sucesso. Objetos e estruturas sofrem cinco vezes esse dano. Criaturas abrigadas a pelo menos 300 metros abaixo do solo sofrem metade do dano. Exceto por esse abrigo subterrâneo, a magia ignora toda cobertura. Se você estiver na explosão, tem vantagem no teste e sofre metade do dano resultante. O efeito mata a vida selvagem, devasta a maior parte das estruturas e reduz a região atingida a uma cratera fumegante. Criaturas, objetos e itens mágicos destruídos pela Obliteração são reduzidos a pó, a menos que sejam eidólicos por natureza; apenas artefatos carregados por eles permanecem.\n\nImunidade Antimagia. Esta magia não pode ser dissipada enquanto você estiver vivo e dentro do alcance de seus efeitos. Se morrer antes do fim da duração, role 1d100 no início de cada minuto restante; com 20 ou menos, a magia termina sem que a Obliteração ocorra.\n\nQueima de Eidomancia Avançada. Ao conjurar esta magia, realize um teste de resistência de Constituição CD 19. Em caso de falha, sofre quatro níveis de exaustão e perde permanentemente a capacidade de conjurá-la. Se a falha elevaria sua exaustão a 6 níveis, ela é definida como 5 e, assim que a magia terminar, seus pontos de vida são reduzidos imediatamente a 0.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":194,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia","Eidomancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-force-horn","name":"Chifre de Força","originalName":"Force Horn","aliases":[],"level":2,"school":"Conjuração","time":"1 ação","range":"1,5 metro","comp":"S","material":"","duration":"1 rodada","classes":"Alma Favorecida, Paladino, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você cria um escudo com chifres e o usa para realizar um ataque corpo a corpo com magia contra um alvo a até 1,5 metro. Em um acerto, o alvo sofre 4d8 de dano perfurante e fica caído. Além disso, sua Classe de Armadura aumenta em uma quantidade igual à metade do nível em que a magia foi conjurada até o início do seu próximo turno.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode adicionar um dado de dano da sua Encarnação ao dano desta magia.","higher":"Quando você conjura esta magia no 3º nível ou superior, o dano aumenta em 2d8 para cada nível acima do 2º.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":194,"category":"Zagalhta's Exolunar Collection","traits":["Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-freezing-lance","name":"Lança Congelante","originalName":"Freezing Lance","aliases":[],"level":1,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"1 minuto","classes":"Druida, Feiticeiro, Bruxo, Mago, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você faz gelo irromper sob os pés de uma criatura que possa ver a até 9 metros. Ela deve realizar um teste de resistência de Constituição, sofrendo 2d8 de dano de frio em caso de falha ou metade em caso de sucesso.\n\nSe o alvo tiver o mesmo tamanho que você ou for menor, também fica impedido pelo gelo em caso de falha. Uma criatura impedida dessa forma pode realizar, em seu turno, um teste de Força contra sua CD para evitar magias, libertando-se em caso de sucesso. Após 1 minuto, o gelo desaparece por conta própria e o efeito termina.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 1º:\n• Você pode escolher um alvo adicional dentro do alcance, e o alcance dobra.\n• O dano da magia aumenta em 1d8.\n• O tamanho máximo de criatura que pode ficar impedida aumenta em duas categorias.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":194,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-frenzied-wyrmbolt","name":"Raio Dracônico Frenético","originalName":"Frenzied Wyrmbolt","aliases":[],"level":6,"school":"Necromancia","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Instantânea","classes":"Feiticeiro, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você faz um raio de energia atingir um ponto que possa ver a até 18 metros. Cada criatura a até 3 metros desse ponto deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 4d8 + 5 de dano elétrico e 4d10 + 5 de dano necrótico, e seu máximo de pontos de vida é reduzido pelo dano necrótico sofrido. Em caso de sucesso, o máximo de pontos de vida é reduzido pelo dano elétrico sofrido. Se essa redução levar o máximo de pontos de vida de uma criatura a 0, ela morre instantaneamente e seu corpo é petrificado.\n\nA redução do máximo de pontos de vida permanece até ser removida por uma magia como Restauração Maior. Enquanto o máximo estiver reduzido dessa maneira, quando o alvo usar Dados de Vida para recuperar pontos de vida, a quantidade curada é reduzida à metade e seu máximo de pontos de vida se recupera pela mesma quantidade efetivamente curada.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode substituir o dano elétrico pelo tipo de dano da sua Encarnação. Se esse tipo for necrótico, ele também conta para a redução do máximo de pontos de vida, mas a magia não causa dano em caso de sucesso no teste de resistência.","higher":"Quando você conjura esta magia no 7º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 6º:\n• Os danos elétrico e necrótico aumentam em 1d8 e 1d10, respectivamente.\n• A distância a partir do ponto escolhido dentro da qual os alvos são atingidos dobra.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":195,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-galactic-meteor","name":"Meteoro Galáctico","originalName":"Galactic Meteor","aliases":[],"level":7,"school":"Evocação","time":"1 ação","range":"144 metros","comp":"S","material":"","duration":"Instantânea","classes":"Feiticeiro, Bruxo, Mago, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você invoca um meteoro de energia cósmica que cai sobre um ponto que possa ver a até 144 metros. Cada criatura em uma esfera de 9 metros de raio centrada nesse ponto deve realizar um teste de resistência de Destreza, sofrendo 4d10 + 5 de dano contundente e 4d10 + 5 de dano de energia em caso de falha, ou metade em caso de sucesso.\n\nBônus de Astromancia. Se conjurar esta magia em um ambiente de gravidade zero, o alcance dobra.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, você pode substituir o dano contundente pelo tipo de dano da sua Encarnação.\n\nQueima de Eidomancia. CD 10 + nível da magia; 3 níveis de exaustão em caso de falha; a magia fica indisponível por 7 dias.","higher":"Quando você conjura esta magia no 8º nível ou superior, o raio da esfera aumenta em 4,5 metros e a magia causa 1d10 adicional de dano contundente e 1d10 adicional de dano de energia para cada nível acima do 7º.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":195,"category":"Zagalhta's Exolunar Collection","traits":["Eidomancia","Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-ghostly-bite","name":"Mordida Fantasmagórica","originalName":"Ghostly Bite","aliases":[],"level":2,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"1 minuto","classes":"Inscritor, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"A forma espectral da cabeça de um dragão aparece e morde uma criatura que você possa ver a até 9 metros, prendendo-a entre as mandíbulas. O alvo deve realizar um teste de resistência de Destreza. Em caso de falha, sofre 3d10 de dano perfurante e fica impedido durante a duração da magia. Ele pode tentar escapar como se estivesse agarrado, usando sua CD para evitar magias como CD de escape.\n\nComo uma ação bônus em seu turno, você pode encerrar a magia antecipadamente para fazer a cabeça dracônica arremessar a criatura até um espaço desocupado que você escolher a até 9 metros.\n\nSe o alvo for três ou mais categorias de tamanho maior que você, não pode ser arremessado e tem vantagem nas tentativas de escapar da condição impedido.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode causar o tipo de dano da sua Encarnação no lugar do dano perfurante.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O dano aumenta em 1d10.\n• O alvo pode ser duas categorias de tamanho adicionais maior que você antes de receber vantagem para escapar e deixar de poder ser arremessado.\n• Você pode escolher um alvo adicional dentro do alcance. Usar a ação bônus para arremessar afeta apenas uma criatura por vez e encerra o efeito somente para ela.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":195,"category":"Zagalhta's Exolunar Collection","traits":["Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-gigaburst","name":"Gigaexplosão","originalName":"Gigaburst","aliases":[],"level":4,"school":"Encantamento","time":"1 ação bônus","range":"Pessoal","comp":"S","material":"","duration":"Instantânea","classes":"Alma Favorecida, Patrulheiro, Feiticeiro, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Como parte desta magia, você pode realizar imediatamente um ataque com arma com vantagem contra um alvo ao alcance, usando uma arma à sua escolha. Depois, durante esse turno, você pode realizar uma ação adicional e uma ação bônus adicional, além das primeiras que normalmente possui. Quaisquer jogadas de ataque ou dano feitas como parte dessa segunda ação completa recebem um bônus igual à metade do nível em que esta magia foi conjurada.\n\nVocê não pode conjurar esta magia no mesmo turno em que usar outra característica, traço ou magia que lhe conceda uma ação ou ação bônus adicional, e não pode usar opções desse tipo pelo restante do turno após conjurá-la.\n\nAo fim do turno em que conjurou esta magia, você recebe 1 ponto de Fadiga de Combate. Se não puder receber mais, sofre uma quantidade de dano irredutível igual a 1d4 × o nível da magia.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":195,"category":"Zagalhta's Exolunar Collection","traits":["Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-glittering-star-curtain","name":"Cortina Estelar Cintilante","originalName":"Glittering Star Curtain","aliases":[],"level":3,"school":"Abjuração","time":"1 ação","range":"18 metros (esfera de 9 metros de raio)","comp":"V, S","material":"","duration":"1 minuto","classes":"Bardo, Druida, Inscritor, Cavaleiro das Pétalas, Patrulheiro, Mago","ritual":false,"concentration":false,"desc":"Você faz um véu cintilante de luzes tremeluzentes preencher uma esfera de 9 metros de raio centrada em um ponto que escolher a até 18 metros. Durante a duração da magia, criaturas que estejam em um plano sobreposto ao plano onde a magia foi conjurada, como o Plano Etéreo, e criaturas invisíveis podem ser vistas fracamente dentro da esfera, contornadas por poeira brilhante. Elas podem ser atacadas e escolhidas como alvo como se estivessem visíveis e no mesmo plano do atacante; esses ataques são tratados como mágicos. Entretanto, ataques contra um alvo que ainda esteja invisível continuam sendo realizados com desvantagem.\n\nCriaturas dentro da esfera também têm desvantagem em testes de Furtividade para se Esconder ou permanecer escondidas.","higher":"Quando você conjura esta magia no 5º nível ou superior, o alcance da magia e o raio da esfera dobram para cada dois níveis acima do 3º.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":196,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-gravitational-purge","name":"Expurgo Gravitacional","originalName":"Gravitational Purge","aliases":[],"level":2,"school":"Evocação","time":"1 ação","range":"Pessoal (9 metros)","comp":"S, V","material":"","duration":"Instantânea","classes":"Druida, Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você libera uma onda invertida de energia que afasta criaturas de você. Cada criatura e objeto não preso a até 9 metros, exceto você, deve realizar um teste de resistência de Força. Em caso de falha, sofre 4d8 de dano de energia e é empurrado para longe de você por 4,5 metros, metade do alcance da magia. Em caso de sucesso, sofre metade do dano e não é empurrado. Se uma criatura empurrada colidir com uma superfície sólida antes de percorrer toda a distância, para e fica caída.\n\nSe uma criatura falhar no teste mas não puder ser movida por causa de outro efeito, fica atordoada até o fim do próximo turno em vez de ser empurrada.\n\nBônus de Astromancia. Se conjurar esta magia em um ambiente de gravidade zero, a distância pela qual as criaturas são empurradas é triplicada.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 2º:\n• O dano de energia aumenta em 1d8.\n• O alcance aumenta em 6 metros, e a distância de empurrão aumenta de acordo.\n• Você pode excluir do efeito uma quantidade de criaturas igual ao seu bônus de proficiência.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":196,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-healing-word","name":"Palavra Curativa","originalName":"Healing Word","aliases":[],"level":1,"school":"Evocação","time":"1 ação bônus","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Bardo, Clérigo, Druida","ritual":false,"concentration":false,"desc":"Uma criatura à sua escolha que você possa ver a até 18 metros recupera pontos de vida iguais a 2d4 + seu modificador de habilidade de conjuração. Esta magia não surte efeito em mortos-vivos ou constructos.\n\nBenção do Curandeiro. Quando esta magia é conjurada por um Clérigo ou Druida, seus d4 se tornam d6.","higher":"Conforme escrito na fonte: quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 2º:\n• A cura aumenta em 2d4.\n• O alvo se recupera de toda Fadiga de Combate que possua e não recebe Fadiga de Combate por ser curado dessa forma.\n• Se estiver caído, o alvo pode usar sua reação para se levantar.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":196,"category":"Zagalhta's Exolunar Collection","traits":["Legado 5.19"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. A fonte classifica esta entrada como uma magia Legacy/revisada; ela foi mantida separada da versão oficial do D&D 5e para preservar as diferenças mecânicas."},{"id":"zagalhta-limited-wish","name":"Desejo Limitado","originalName":"Limited Wish","aliases":[],"level":7,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"Instantânea (Especial)","classes":"Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você dobra a realidade ao seu redor ao pronunciar um desejo de potencial limitado. Escolha um dos efeitos abaixo:\n• Declare um curso de ação que uma criatura a até 18 metros possa concluir em até 1 hora. Durante esse período, quando ela falhar em uma jogada de ataque, teste de atributo ou teste de resistência associado a essa ação, pode usar a reação para adicionar o nível desta magia ao resultado, possivelmente alterando o desfecho.\n• Escolha uma criatura dentro do alcance. Ela se recupera de todos os efeitos e condições que poderiam ser removidos por Restauração Maior.\n• Uma criatura escolhida dentro do alcance torna-se resistente a todo dano até concluir um Descanso e recebe pontos de vida temporários iguais a 1d8 × o nível em que esta magia foi conjurada.\n• Uma criatura escolhida dentro do alcance recebe imediatamente os benefícios de um Descanso Curto, mas só pode gastar uma quantidade de Dados de Vida igual ou inferior ao nível desta magia e não recupera espaços de magia.\n• Você conjura imediatamente outra magia que conheça ou tenha preparada, de nível igual ou inferior à metade do nível em que Desejo Limitado foi conjurado. Cada alvo dessa magia falha em seu primeiro teste de resistência contra seus efeitos como se tivesse obtido resultado 1 no d20, sem modificador.\n• Você pode produzir os efeitos de qualquer magia de qualquer lista que possua tempo de conjuração de 1 ação ou 1 ação bônus; ela é conjurada no mesmo nível de Desejo Limitado. Depois disso, você conhece essa magia como se a tivesse aprendido ou preparado até concluir um Descanso Curto ou Longo.\n• Se alguma característica sua o especializa em uma escola ou grupo de magia específico, você pode produzir os efeitos de qualquer magia dessa escola ou grupo que exija 1 ação ou 1 ação bônus; essa magia é tratada como se fosse conjurada com um espaço de 9º nível.\n\nPara qualquer efeito de magia produzido por Desejo Limitado, você deve possuir e utilizar o componente material exigido ou perder uma quantidade de ouro equivalente ao valor desse componente, fazendo surgir uma cópia que é imediatamente usada, permanece pelo tempo necessário e então desaparece.\n\nQueima de Eidomancia. A CD é 10 + o nível de Desejo Limitado ou o nível do efeito de magia produzido, o que for maior. Em uma falha, você não sofre exaustão; em vez disso, cada um de seus valores de atributo é reduzido em 2d4. Cada valor recupera 1 ponto perdido sempre que você conclui um Descanso Longo. A magia fica indisponível por 7 dias.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":196,"category":"Zagalhta's Exolunar Collection","traits":["Eidomancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-magma-wave","name":"Onda de Magma","originalName":"Magma Wave","aliases":[],"level":4,"school":"Conjuração","time":"1 ação","range":"linha de 9 metros","comp":"S","material":"","duration":"Instantânea","classes":"Druida, Feiticeiro, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Uma onda de magma parte de você, preenchendo uma linha de 12 metros de comprimento e 6 metros de largura. Cada alvo nessa área deve realizar um teste de resistência de Destreza, sofrendo 6d6 de dano de fogo em caso de falha ou metade em caso de sucesso. O magma permanece nesses espaços por 1 minuto, transformando-os em terreno difícil.\n\nUma criatura que comece o turno em um espaço coberto por magma ou entre em um desses espaços pela primeira vez no turno sofre 1d6 de dano de fogo. Cada espaço é considerado individualmente; uma criatura grande que entre em vários espaços simultaneamente durante o movimento conta apenas um espaço por vez.\n\nUm espaço deixa de conter magma se estiver preenchido por um líquido que não seja quente ou inflamável, ou se o espaço sofrer dano de frio.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível.","higher":"Conforme escrito na fonte: quando você conjura esta magia no 5º nível ou superior, pode escolher um dos efeitos a seguir para cada nível acima do 3º:\n• O dano inicial aumenta em 1d6.\n• A onda fica 3 metros mais longa e 1,5 metro mais larga.\n• Você se torna imune aos efeitos do magma produzido por esta magia durante a duração dele.\n• O dano dos espaços cobertos de magma aumenta para d8 (1 nível), d10 (2 níveis) ou d12 (3 níveis).","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":197,"category":"Zagalhta's Exolunar Collection","traits":["Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. A fonte imprime alcance como linha de 30 pés, enquanto a descrição define a onda como uma linha de 40 pés por 20 pés; ambos os valores foram preservados nos respectivos campos."},{"id":"zagalhta-momentous-weapon","name":"Arma Monumental","originalName":"Momentous Weapon","aliases":[],"level":1,"school":"Encantamento","time":"1 ação","range":"Toque","comp":"S","material":"","duration":"Concentração, até 1 hora","classes":"Clérigo, Alma Favorecida, Inscritor, Paladino, Patrulheiro","ritual":false,"concentration":true,"desc":"Uma arma que você toca fica encantada durante a duração da magia e é recoberta por uma aura densa que reforça seus golpes e seu peso. Durante esse período, ela recebe as propriedades a seguir:\n• A arma causa um dado adicional de dano.\n• Para efeitos, características e traços baseados em tamanho, os ataques feitos com ela são considerados provenientes de uma criatura uma categoria de tamanho maior que o portador.\n• Quando a arma obtém um acerto crítico, o alvo fica caído, desde que não seja resistente ao dano da arma.","higher":"Conforme escrito na fonte: quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível da magia acima do 2º:\n• A categoria de tamanho considerada para o portador aumenta em uma categoria.\n• Você não precisa se concentrar nesta magia.\n• O dano adicional passa a ser dois dados de dano (1 nível) ou três dados de dano (3 níveis).\n• (2 níveis) Este efeito se estende a todos os ataques feitos pelo alvo.\n• (4 níveis) O dano da arma não pode ser resistido em razão do tamanho do portador ou do alvo.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":197,"category":"Zagalhta's Exolunar Collection","traits":[],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-mass-cure-wounds","name":"Curar Ferimentos em Massa","originalName":"Mass Cure Wounds","aliases":[],"level":5,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Bardo, Clérigo, Druida","ritual":false,"concentration":false,"desc":"Uma onda de energia curativa se espalha a partir de um ponto à sua escolha a até 18 metros. Escolha até seis criaturas em uma esfera de 9 metros de raio centrada nesse ponto. Cada alvo recupera pontos de vida iguais a 4d8 + seu modificador de habilidade de conjuração. Esta magia não surte efeito em mortos-vivos ou constructos.\n\nBenção do Curandeiro. Quando esta magia é conjurada por um Clérigo ou Druida, seus d8 se tornam d10.","higher":"Quando você conjura esta magia no 6º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 5º:\n• A cura aumenta em 1d8.\n• Você pode escolher dois alvos adicionais dentro do alcance.\n• O alcance da magia dobra.\n• (2 níveis) Os alvos se recuperam de toda Fadiga de Combate e não recebem Fadiga de Combate por serem curados dessa forma.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":197,"category":"Zagalhta's Exolunar Collection","traits":["Legado 5.19"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. A fonte classifica esta entrada como uma magia Legacy/revisada; ela foi mantida separada da versão oficial do D&D 5e para preservar as diferenças mecânicas."},{"id":"zagalhta-mass-healing-word","name":"Palavra Curativa em Massa","originalName":"Mass Healing Word","aliases":[],"level":3,"school":"Evocação","time":"1 ação bônus","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Clérigo, Alma Favorecida","ritual":false,"concentration":false,"desc":"Ao pronunciar palavras de restauração, até seis criaturas à sua escolha que você possa ver a até 18 metros recuperam pontos de vida iguais a 2d4 + seu modificador de habilidade de conjuração. Esta magia não surte efeito em mortos-vivos ou constructos.\n\nBenção do Curandeiro. Quando esta magia é conjurada por um Clérigo ou Druida, seus d4 se tornam d6.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 3º:\n• A cura aumenta em 1d4.\n• Você pode escolher uma criatura adicional como alvo.\n• O alcance aumenta em 9 metros.\n• Se estiverem caídos, seus alvos podem usar a reação para se levantar.\n• (3 níveis) Os alvos se recuperam de toda Fadiga de Combate e não recebem Fadiga de Combate por esta cura.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":197,"category":"Zagalhta's Exolunar Collection","traits":["Legado 5.19"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. A fonte classifica esta entrada como uma magia Legacy/revisada; ela foi mantida separada da versão oficial do D&D 5e para preservar as diferenças mecânicas."},{"id":"zagalhta-occluding-mists","name":"Névoas Oclusivas","originalName":"Occluding Mists","aliases":[],"level":2,"school":"Abjuração","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Druida, Cavaleiro das Pétalas, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você lança uma esfera de névoa contra um alvo a até 9 metros, realizando um ataque à distância com magia. Em um acerto, a névoa envolve o alvo e o acompanha enquanto ele se move e age. Durante a duração da magia, o alvo tem desvantagem em jogadas de ataque e testes de Percepção, e todos os tipos de visão que possua, exceto sentido sísmico, percepção às cegas e visão verdadeira, ficam limitados a 6 metros; além dessa distância, ele está cego.\n\nAo final de cada um de seus turnos, uma criatura afetada pode realizar um teste de resistência de Sabedoria, encerrando o efeito em caso de sucesso.\n\nVocê só pode escolher como alvo criaturas que sejam, no máximo, uma categoria de tamanho maiores que você.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 2º:\n• O alcance dobra.\n• Você pode escolher um alvo adicional dentro do alcance, realizando um ataque separado para cada um.\n• O tamanho máximo de criatura que pode ser alvo aumenta em duas categorias.\n• (3 níveis) A magia deixa de exigir concentração; você pode encerrar seus efeitos sobre uma ou mais criaturas como uma ação bônus.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":198,"category":"Zagalhta's Exolunar Collection","traits":["Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-open-communication","name":"Comunicação Aberta","originalName":"Open Communication","aliases":[],"level":3,"school":"Adivinhação","time":"1 ação","range":"Visão","comp":"V, S","material":"","duration":"10 minutos","classes":"Bardo, Patrulheiro, Mago","ritual":false,"concentration":false,"desc":"Escolha uma nave exolunar, unidade frame ou fonte de uma assinatura de portal que você consiga ver. O operador recebe uma solicitação para abrir comunicação com você e decide como ela ocorrerá: pode rejeitá-la completamente, encerrando a magia; permitir apenas áudio; permitir que um holograma seu apareça no veículo e projete seus sentidos; ou aceitar apenas uma mensagem gravada.\n\nA solicitação pode conter texto ou uma gravação na sua voz com até 50 palavras. Uma criatura familiarizada com você, com a nave em que você está ou com o tipo dessa nave recebe essa informação junto da solicitação. Se ela for rejeitada, os recursos usados para conjurar esta magia, inclusive o espaço de magia, não são gastos.\n\nO receptor escolhe onde a comunicação ocorre em sua nave ou instalação, normalmente a ponte, uma central de comunicações ou a cabine de uma unidade frame. Se o contato for estabelecido, vocês podem se comunicar nas condições escolhidas durante a duração. Qualquer lado pode encerrar a magia antecipadamente como uma ação.\n\nSomente Áudio. Você pode ser ouvido do outro lado e escutar o que for dito na área definida pelo receptor, mas nenhum lado pode ver o outro.\n\nÁudio e Vídeo. Vocês se comunicam por telas, alto-falantes e equipamentos disponíveis. Seu ponto de vista permanece estacionário no local escolhido do outro lado. As telas mostram sua aparência e movimentos, omitindo o cenário ao seu redor.\n\nHolograma Estacionário. Um constructo granuloso de luz com sua aparência surge. Você pode ver tudo a até 9 metros dele. Sentidos especiais, como percepção às cegas ou visão verdadeira, não são projetados, mas você enxerga e ouve pelo holograma sem perder os sentidos do próprio corpo. Ele não pode sair do espaço autorizado, e criaturas próximas podem ver e ouvir você como se estivesse presente.\n\nHolograma Errante. Funciona como Holograma Estacionário, mas pode vagar pelas áreas autorizadas pelo receptor. Você move o holograma pela vontade, até 9 metros por rodada, sem gastar seu próprio movimento.","higher":"Conforme escrito na fonte: quando você conjura esta magia no 4º nível ou inferior, pode escolher um dos efeitos a seguir para cada nível acima do 3º:\n• Você pode escolher uma nave em órbita do mesmo planeta (1 nível), no mesmo sistema solar (3 níveis) ou no mesmo plano de existência (5 níveis).\n• Você pode tentar comunicar-se com um alvo adicional, incluindo-o na mesma comunicação.\n• (2 níveis) Você pode deixar uma mensagem gravada, ditada em até 1 minuto, que o alvo recebe e pode reproduzir livremente.\n• Se conjurada no 9º nível, independentemente de como os níveis adicionais foram gastos, o alvo não pode rejeitar a solicitação; o Mestre decide onde a comunicação ocorre do outro lado, e você escolhe o tipo de comunicação.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":198,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-outer-breath","name":"Respiração no Vazio","originalName":"Outer Breath","aliases":[],"level":0,"school":"Transmutação","time":"1 ação","range":"Toque","comp":"S","material":"","duration":"10 minutos","classes":"Bardo, Druida, Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Uma criatura que você toca recebe a capacidade de respirar no vazio do espaço durante a duração, produzindo ar dentro dos próprios pulmões conforme necessário. Durante esse período, ela também consegue falar no vácuo, e sua voz pode ser ouvida como se estivesse em um ambiente com ar capaz de conduzir o som. Esta magia não protege contra a inalação de gases ou substâncias químicas tóxicas e não permite respirar outras substâncias, como água ou outros líquidos.\n\nAprimoramento de Truque. No 5º nível, a duração aumenta para 1 hora; no 11º nível, para 8 horas; e no 17º nível, para 24 horas.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":199,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-passage-of-light","name":"Passagem de Luz","originalName":"Passage of Light","aliases":[],"level":2,"school":"Encantamento","time":"1 ação","range":"3 metros","comp":"S","material":"","duration":"Instantânea","classes":"Alma Favorecida, Paladino, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Escolha uma quantidade de criaturas a até 3 metros igual ou inferior ao nível em que a magia foi conjurada; você deve estar entre elas. Cada escolhida é envolvida por luz sagrada e pode usar sua reação para tornar-se uma rajada de energia que avança até um alvo a até 9 metros dela e o ataca; você, como conjurador, não precisa gastar reação. Cada criatura escolhe seu próprio alvo e realiza contra ele um ataque com uma arma que esteja carregando. Em um acerto, causa o dano da arma + 1d10 de dano radiante e surge em um espaço desocupado adjacente ao alvo.\n\nEsses ataques são considerados mágicos caso já não fossem.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, a magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Qualquer Cavaleiro Dracônico que ataque como parte desta magia pode transformar o dano causado no tipo de dano da própria Encarnação.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 2º:\n• O alcance da magia e a distância dentro da qual cada criatura pode escolher um alvo dobram.\n• (2 níveis) O dano radiante aumenta em 1d10.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":199,"category":"Zagalhta's Exolunar Collection","traits":["Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-phantom-breath","name":"Sopro Fantasma","originalName":"Phantom Breath","aliases":[],"level":1,"school":"Abjuração","time":"1 ação bônus","range":"Pessoal (9 metros)","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Druida, Cavaleiro das Pétalas, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você se envolve em um manto que corrói o próprio espaço. Uma vez ao conjurar esta magia, e novamente como uma ação bônus enquanto estiver envolvido pelo manto, você pode se teleportar para um espaço desocupado que possa ver a até 9 metros.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O alcance aumenta em 9 metros.\n• (2 níveis) Ataques feitos contra você têm desvantagem durante a duração.\n• (3 níveis) A magia deixa de exigir concentração, mas você pode encerrá-la como uma reação ou ação bônus.\n• (3 níveis) Enquanto estiver sob seus efeitos, você recebe deslocamento de teleporte igual a 9 metros ou à metade do alcance da magia, o que for maior.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":199,"category":"Zagalhta's Exolunar Collection","traits":["Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-power-word-roar","name":"Palavra de Poder: Rugido","originalName":"Power Word Roar","aliases":[],"level":8,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V","material":"","duration":"Instantânea","classes":"Feiticeiro, Mago, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra de poder explosivo que assalta até dez criaturas à sua escolha a até 36 metros. Cada uma deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 10d10 + 30 de dano trovejante, fica surda e perde a concentração; em caso de sucesso, sofre metade do dano. Alvos com menos de 100 pontos de vida ficam automaticamente surdos e perdem a concentração, mas podem repetir o teste de resistência ao fim de cada um de seus turnos, encerrando esses efeitos em caso de sucesso.\n\nCriaturas imunes a dano trovejante não são afetadas por esta magia.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, alvos que obtenham sucesso no teste são tratados, para os efeitos acima, como se possuíssem menos de 100 pontos de vida.\n\nQueima de Eidomancia. CD 10 + nível da magia; 4 níveis de exaustão em caso de falha; a magia fica indisponível por 7 dias.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":199,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma","Eidomancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-propulsion","name":"Propulsão","originalName":"Propulsion","aliases":[],"level":2,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"1 hora","classes":"Clérigo, Alma Favorecida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Uma quantidade de criaturas dentro de 18 metros igual ao nível em que esta magia foi conjurada recebe deslocamento de aceleração 0-G igual ao dobro de seu deslocamento base. Você escolhe as criaturas e pode incluir a si mesmo.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":199,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-radiant-barrage","name":"Barragem Radiante","originalName":"Radiant Barrage","aliases":[],"level":2,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Clérigo, Alma Favorecida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você produz quatro rajadas de energia cósmica. Cada uma dispara contra um alvo à sua escolha a até 36 metros como um ataque à distância com magia. Várias rajadas podem escolher o mesmo alvo, mas cada uma acerta separadamente. Em um acerto, uma rajada causa 1d8 de dano radiante.\n\nBônus de Astromancia. Quando conjurada em um ambiente de gravidade zero, o alcance desta magia dobra e cada rajada causa 1d8 adicional de dano radiante.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 2º:\n• Você produz uma rajada adicional.\n• Cada rajada causa 1d8 adicional de dano.\n• O alcance dobra.\n• (2 níveis) Cada criatura atingida por uma rajada deve realizar um teste de resistência de Constituição; em caso de falha, fica cega até o início do seu próximo turno.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":200,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-rain-of-light","name":"Chuva de Luz","originalName":"Rain of Light","aliases":[],"level":1,"school":"Evocação","time":"1 ação","range":"6 metros","comp":"S","material":"","duration":"Instantânea","classes":"Clérigo, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Uma rosa etérea de energia radiante floresce acima de você, saturando a atmosfera e fazendo feixes de luz choverem do alto. Cada criatura à sua escolha a até 6 metros deve realizar um teste de resistência de Destreza, sofrendo 2d8 de dano radiante em caso de falha. Alvos que falharem por 5 ou mais também ficam cegos até o início do seu próximo turno.\n\nBônus do Cavaleiro Dracônico. Quando esta magia é conjurada por um Cavaleiro Dracônico, é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode causar o tipo de dano da sua Encarnação no lugar do dano radiante.","higher":"Conforme escrito na fonte: quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O dano aumenta em 1d8.\n• O alcance dobra.\n• Criaturas que ficarem cegas permanecem assim por 1 minuto e podem realizar um teste de resistência de Constituição ao fim de cada turno, encerrando o efeito em caso de sucesso.\n• (3 níveis) Alvos que obtenham sucesso no teste sofrem metade do dano da magia, em vez de nenhum.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":200,"category":"Zagalhta's Exolunar Collection","traits":["Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-ravenous-tornado","name":"Tornado Voraz","originalName":"Ravenous Tornado","aliases":[],"level":8,"school":"Evocação","time":"1 ação","range":"150 metros","comp":"V, S, M (uma pena de ave e um grande leque ornamental)","material":"uma pena de ave e um grande leque ornamental","duration":"Concentração, até 10 minutos","classes":"Clérigo, Druida, Feiticeiro","ritual":false,"concentration":true,"desc":"Canalizando as forças do céu, você cria um vórtice crepitante de vento e relâmpagos na forma de um cilindro de 60 metros de altura e 9 metros de raio, centrado em um ponto que possa ver a até 150 metros. Quando o vórtice aparece, cada criatura em sua área realiza um teste de resistência de Constituição. Em caso de falha, sofre 5d8 de dano contundente e 5d8 de dano elétrico e perde a concentração; em caso de sucesso, sofre metade do dano e mantém a concentração.\n\nVentos Devastadores. Uma criatura que começa o turno dentro do vórtice realiza um teste de resistência de Força. Em caso de falha, sofre 3d8 de dano contundente e 3d8 de dano elétrico e fica caída; em caso de sucesso, sofre metade do dano. Uma criatura que começa o turno a até 4,5 metros do vórtice ou entra nessa distância pela primeira vez no turno também realiza o teste, mas com vantagem. Em caso de falha, sofre os mesmos efeitos e é puxada para o espaço mais próximo dentro do vórtice depois de cair.\n\nUma criatura que falhe nesse teste por 5 ou mais também é puxada até a metade da altura do vórtice, 30 metros no ar, e permanece suspensa até obter sucesso no teste. Quando consegue, é lançada pela lateral e despenca em direção a um ponto que você escolher a até 9 metros da borda do cilindro. Uma criatura suspensa acompanha o vórtice quando você muda sua posição.\n\nAmbiente Destrutivo. O interior do vórtice é terreno difícil. Ataques à distância que se originem dentro dele ou atravessem sua borda têm desvantagem. Criaturas que voem, pairem ou se desloquem por aceleração 0-G dentro do cilindro têm desvantagem em jogadas de ataque e testes de resistência de Força e Destreza.\n\nDirecionar Cativo. Como uma ação bônus, você pode alterar coletivamente em até 15 metros a posição de quaisquer criaturas suspensas dentro do vórtice.\n\nDirecionar Vórtice. Como uma ação, você pode mover o vórtice até 18 metros em linha reta.\n\nCobertura Torrencial. A borda do vórtice fornece três quartos de cobertura para quem está dentro contra quem está fora e vice-versa.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":200,"category":"Zagalhta's Exolunar Collection","traits":[],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-repair-construct","name":"Reparar Constructo","originalName":"Repair Construct","aliases":[],"level":2,"school":"Transmutação","time":"1 ação","range":"Toque","comp":"V, S","material":"","duration":"Instantânea","classes":"Clérigo, Inscritor, Patrulheiro, Feiticeiro","ritual":false,"concentration":false,"desc":"Um constructo voluntário que você toca recebe um dos benefícios a seguir:\n• Restaurar. Ele gasta imediatamente uma quantidade de Dados de Vida igual ao nível em que esta magia foi conjurada, adicionando seu modificador de habilidade de conjuração a cada rolagem, e recupera pontos de vida iguais à soma.\n• Reabastecer. Ele recupera uma quantidade de Dados de Vida igual à metade do nível em que esta magia foi conjurada.\n\nBônus de Pegada. Se você conjurar esta magia através de uma unidade frame, pode rolar uma quantidade adicional de Dados de Vida conforme a opção Reabastecer, mesmo se estiver escolhendo a própria unidade como alvo. Esses dados não são gastos pelo alvo e seus resultados são adicionados à cura. A quantidade adicional é determinada pela diferença de Pegada entre vocês, calculada como se fossem dados de dano.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":201,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-rose-tornado","name":"Tornado de Rosas","originalName":"Rose Tornado","aliases":[],"level":4,"school":"Abjuração","time":"1 ação","range":"Pessoal (esfera de 9 metros de raio)","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você manifesta uma zona de influência na forma de uma forte corrente circular de vento repleta de pétalas, preenchendo uma esfera de 9 metros de raio centrada em você. Você e seus aliados dentro da área recebem, quando a magia é conjurada e no início de cada um de seus turnos, pontos de vida temporários iguais ao nível em que a magia foi conjurada + 1d6. Enquanto possuírem esses pontos de vida temporários, mesmo que estejam fora da esfera, recebem os benefícios a seguir:\n• Seus ataques são considerados mágicos.\n• Seus ataques ignoram Limiares de Dano.\n• Ataques com arma realizados contra eles têm desvantagem.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível.","higher":"Quando você conjura esta magia no 6º nível ou superior, ela concede 1d6 adicional de pontos de vida temporários para cada dois níveis acima do 4º.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":201,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-ruinous-end","name":"Fim Ruinoso","originalName":"Ruinous End","aliases":[],"level":8,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"S, M (uma manopla feita dos ossos de um dragão ancestral, com uma gema de pelo menos 5.000 po incrustada)","material":"uma manopla feita dos ossos de um dragão ancestral, com uma gema de pelo menos 5.000 po incrustada","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você reúne energias primordiais em uma esfera de destruição condensada que aparece em um ponto a até 18 metros e paira até 9 metros acima do chão. Ela ocupa um espaço uma categoria de tamanho maior que você e permanece durante a duração da magia.\n\nRuínas Explosivas. Uma vez ao conjurar a magia e novamente como uma ação bônus nos turnos seguintes, você dispara três rajadas de relâmpago primordial da esfera, cada uma contra um alvo diferente a até 18 metros dela, realizando ataques à distância com magia. Em um acerto, cada rajada causa 2d10 de dano elétrico e 2d10 de dano necrótico.\n\nProximidade. Uma criatura que comece o turno em um espaço ocupado pela esfera ou entre nele pela primeira vez no turno deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 8d10 de dano necrótico e rola 1d4: com resultado 1–3, sofre 1 ponto de Fadiga de Combate; com 4, sofre 1 nível de exaustão.\n\nMovimento. Como uma ação, você pode comandar a esfera para se mover até 9 metros, metade do alcance da magia, para um espaço à sua escolha. Se ela passar por criaturas sem terminar no espaço delas, essas criaturas realizam um teste de resistência de Destreza e sofrem 5d10 de dano necrótico em caso de falha.\n\nDestruição Mútua. Se você for reduzido a 0 pontos de vida ou perder a concentração nesta magia por causa de dano, pode usar sua reação para ativar Devastação Espiralante antes que a magia termine por completo.\n\nDissolução Não Mágica. Se os efeitos desta magia atravessarem material não mágico ou um alvo estiver atrás ou dentro de cobertura não mágica, o material ou cobertura se desintegra imediatamente.\n\nDevastação Espiralante. Enquanto estiver a até 18 metros da esfera, você pode usar sua ação para encerrar a magia antecipadamente e arremessar toda a esfera contra um espaço que possa ver a até duas vezes o alcance da magia a partir dela. Cada alvo a até 12 metros desse ponto realiza um teste de resistência de Constituição como se estivesse exposto ao efeito Proximidade. Ao escolher esta ação, você pode se teleportar para dentro da esfera, desaparecendo até a resolução do efeito e então surgindo no espaço escolhido quando a magia termina.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, a CD da Queima de Eidomancia desta magia não pode exceder 20, e uma falha causa apenas dois níveis de exaustão. Você pode substituir qualquer dano necrótico da magia pelo tipo de dano da sua Encarnação.\n\nQueima de Eidomancia. CD 10 + nível da magia + número de turnos desde que foi conjurada; 4 níveis de exaustão em caso de falha; a magia fica indisponível por 7 dias.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":201,"category":"Zagalhta's Exolunar Collection","traits":["Eidomancia","Encarnações de Milarose"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-seeking-spear","name":"Lança Perseguidora","originalName":"Seeking Spear","aliases":[],"level":1,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Paladino, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você cria uma série de lanças, cada uma ligada por uma corrente a um único anel que as conecta. Cada lança dispara contra uma criatura diferente à sua escolha a até 18 metros como um ataque à distância com magia. Nenhum par de alvos pode estar separado por mais de uma distância entre 1,5 e 6 metros, escolhida por você ao conjurar a magia. Uma criatura atingida sofre 1d6 de dano perfurante e fica vinculada à magia quando a lança se transforma em um grilhão preso a ela.\n\nCriaturas presas pelos grilhões não podem se afastar entre si além da distância máxima escolhida. Cada uma pode usar sua ação no turno para realizar um teste de Força contra sua CD de magia, libertando-se em caso de sucesso. Se em algum momento apenas uma criatura continuar presa, ela sofre 1d6 adicional de dano perfurante e correntes surgem para prendê-la no lugar, deixando-a impedida durante a duração. Ela pode se libertar da mesma forma que dos grilhões.\n\nA quantidade de criaturas que você pode escolher como alvo é igual a duas vezes o nível em que esta magia foi conjurada.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode causar o tipo de dano da sua Encarnação no lugar do dano perfurante.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• As duas instâncias de dano da magia aumentam em 1d6.\n• Você pode escolher alvos que estejam até 3 metros mais afastados entre si. Isso não aumenta a distância máxima escolhida; criaturas acorrentadas além dessa distância são puxadas umas em direção às outras até terminarem em espaços que respeitem a separação correta.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":202,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-shroud-of-spines","name":"Manto de Espinhos","originalName":"Shroud of Spines","aliases":[],"level":2,"school":"Transmutação","time":"1 ação","range":"Pessoal (6 metros)","comp":"S","material":"","duration":"1 minuto","classes":"Druida, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Seu corpo fica coberto por uma camada de espinhos de pedra durante 1 minuto. Enquanto os possuir, você é resistente a dano contundente, perfurante e cortante. Além disso, sempre que sofrer dano de um ataque com arma originado a até 6 metros, pode usar sua reação para atingir o atacante com os espinhos, causando 1d8 de dano perfurante.\n\nA magia termina antecipadamente se você sofrer um acerto crítico ou for reduzido a 0 pontos de vida.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode substituir o dano perfurante pelo tipo de dano da sua Encarnação.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 2º:\n• O dano aumenta em 1d8.\n• O alcance dobra.\n• (2 níveis) Uma criatura que acertar você com um ataque originado dentro de metade do alcance da magia sofre automaticamente o dano dos espinhos, sem exigir reação. Esse dano só pode ocorrer uma vez por ataque.\n• (5 níveis) Você fica imune a dano perfurante, cortante e contundente durante a duração.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":202,"category":"Zagalhta's Exolunar Collection","traits":["Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-slipstream-gate","name":"Portal de Esteira Astral","originalName":"Slipstream Gate","aliases":[],"level":4,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Bardo, Druida, Inscritor, Patrulheiro, Mago","ritual":false,"concentration":true,"desc":"Escolha um ponto a até 9 metros e outro ponto que possa ver a até dez vezes o alcance da magia. Um portal astral simpático se abre entre eles, semelhante ao criado pela magia Portal Menor, grande o bastante para criaturas de até o dobro do seu tamanho entrarem.\n\nAté a magia terminar, criaturas podem atravessar um portal e emergir do outro. Na primeira vez em que uma criatura atravessa um dos portais em cada turno, pode mover-se imediatamente uma distância adicional igual a 1,5 metro × o nível em que esta magia foi conjurada. Se parar de se mover ou realizar qualquer outra ação, o movimento adicional restante é perdido.\n\nBônus de Astromancia. Em um ambiente de gravidade zero, o alcance da magia é triplicado.","higher":"Conforme escrito na fonte: quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 3º:\n• O alcance aumenta em 9 metros.\n• Você pode criar um portal adicional dentro do alcance aumentado; uma criatura que atravesse qualquer portal astral pode escolher por qual deles emerge.\n• A magia deixa de exigir concentração, mas ao fim de cada um de seus turnos você deve usar uma ação bônus para sustentá-la ou ela termina.\n• (2 níveis) A magia deixa de exigir concentração.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":202,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-slow","name":"Lentidão","originalName":"Slow","aliases":[],"level":3,"school":"Transmutação","time":"1 ação","range":"36 metros","comp":"V, S, M (uma gota de melaço)","material":"uma gota de melaço","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você altera o tempo ao redor de até seis criaturas à sua escolha em um cubo de 12 metros dentro de 36 metros. Cada alvo deve realizar um teste de resistência de Sabedoria; em caso de falha, fica lento durante a duração da magia.\n\nUma criatura lenta dessa forma tem seu deslocamento reduzido à metade, sofre penalidade de −2 na CA e em testes de resistência de Destreza e, independentemente de habilidades ou itens mágicos, não pode realizar mais de um ataque corpo a corpo ou à distância por turno.\n\nSe uma criatura afetada tentar conjurar uma magia com tempo de conjuração de 1 ação, role 1d20. Com 11 ou mais, a magia não produz efeito até o próximo turno da criatura, quando ela deve gastar sua ação para concluí-la; se não puder ou não o fizer, a magia é desperdiçada.\n\nAo fim de cada um de seus turnos, uma criatura afetada realiza outro teste de resistência de Sabedoria, encerrando o efeito sobre si em caso de sucesso.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 3º:\n• Você pode escolher até duas criaturas adicionais dentro do alcance.\n• O tamanho do cubo aumenta em 6 metros.\n• A penalidade na CA e nos testes de resistência de Destreza aumenta em 1.\n• O resultado no d20 necessário para atrasar a conjuração de uma magia diminui em 2.\n• (2 níveis) A magia deixa de exigir concentração; você pode encerrar seus efeitos sobre uma ou mais criaturas como uma ação bônus.\n• (3 níveis) Você conjura esta magia como uma ação bônus.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":202,"category":"Zagalhta's Exolunar Collection","traits":["Legado 5.19"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. A fonte classifica esta entrada como uma magia Legacy/revisada; ela foi mantida separada da versão oficial do D&D 5e para preservar as diferenças mecânicas."},{"id":"zagalhta-sovereignty","name":"Soberania","originalName":"Sovereignty","aliases":[],"level":5,"school":"Transmutação","time":"1 minuto","range":"Pessoal","comp":"V, S","material":"","duration":"1 hora","classes":"Bruxo","ritual":false,"concentration":false,"desc":"Você reúne energia eidomântica ao seu redor e a molda no corpo de uma transformação titânica. Sua aparência torna-se uma representação artificial, porém divina, de uma fera semelhante a um deus, dragão, titã ou outro ser que considere apropriado. Durante a transformação, recebe os benefícios a seguir.\n\nÀ Prova de Dissipação. Esta magia não pode ser dissipada, anulada ou impedida por Campo Antimagia, Dissipar Magia, Contramágica ou efeitos semelhantes de negação de magia.\n\nEscalonamento de Efeitos. O alcance, tamanho e dano de efeitos produzidos por seus itens, magias, características ou outros efeitos são modificados de acordo com seu tamanho. Para calcular a alteração, use as regras de diferença de Pegada de Unidades Frame e considere cada duas categorias de tamanho que você aumentou como um aumento de 1 ponto de Pegada.\n\nNatureza Eidólica. Seus ataques são mágicos e eidólicos.\n\nResistência Macro. Você se torna resistente a dano não eidólico causado por qualquer criatura duas ou mais categorias de tamanho menor que você.\n\nMovimento. Para cada categoria de tamanho que aumentar, cada um de seus deslocamentos aumenta em 3 metros. Deslocamentos de aceleração 0-G aumentam pelo dobro disso.\n\nArmadura e Armas Naturais. Você recebe um bônus na CA, jogadas de ataque e testes de resistência igual à metade do nível em que esta magia foi conjurada. Também ganha um ataque com arma natural que causa dano contundente, perfurante ou cortante, conforme apropriado, podendo usar sua habilidade de conjuração, Força ou Destreza nas jogadas de ataque e dano. Esse ataque causa 1d8 para cada categoria de tamanho acima de Médio que você possuir.\n\nMudança de Tamanho. Seu tamanho é tratado como Imenso ou aumenta em duas categorias, o que for maior. Seu alcance aumenta em 1,5 metro para cada duas categorias que crescer, e suas armas causam um dado adicional de dano da arma para cada duas categorias.\n\nPontos de Vida Temporários. Você recebe 10 pontos de vida temporários × o nível em que a magia foi conjurada.\n\nTérmino. Quando o alvo desta magia é reduzido a 0 pontos de vida, no início de cada turno deve realizar um teste de concentração com CD 13 + o nível em que a magia foi conjurada. Em caso de falha, o efeito termina imediatamente.\n\nNatureza Incomum. Enquanto transformado, você não pode sufocar por falta de ar, mas continua sujeito a efeitos que exijam respiração.\n\nSeleção de Equipamento. Você pode produzir réplicas ampliadas das armas, armaduras e itens sintonizados que carregava no momento da transformação. Não pode usar poções, elixires, bálsamos ou outros itens anteriormente portáteis que exijam consumo, mas pode produzir os efeitos de itens mágicos ou quinquilharias portáteis, como uma Pedra da Boa Sorte ou Colar de Bolas de Fogo.\n\nBônus do Cavaleiro Dracônico. Quando o alvo transformado é um Cavaleiro Dracônico, a magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Esses níveis adicionais não são considerados para a CD da Queima de Eidomancia nem para o efeito Término. Um Cavaleiro Dracônico sempre assume uma forma semelhante a um dragão, embora sua estética possa ser alienígena.\n\nQueima de Eidomancia. CD 10 + nível da magia; 2 níveis de exaustão em caso de falha; a magia fica indisponível por 7 dias. O teste só é realizado quando os efeitos da magia terminam.","higher":"Conforme escrito na fonte: quando você conjura esta magia no 5º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 4º:\n• A quantidade de categorias de tamanho que você aumenta cresce em duas.\n• Você recebe 5 pontos de vida temporários adicionais por nível em que a magia foi conjurada.\n• Você ganha um deslocamento adicional que não possuía, igual ao seu deslocamento base, escolhendo entre escavação, escalada, voo ou aceleração 0-G.\n• (2 níveis) Você pode conjurar esta magia como uma ação.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":203,"category":"Zagalhta's Exolunar Collection","traits":["Eidomancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-stadyfyre-s-principle","name":"Princípio de Stadyfyre","originalName":"Stadyfyre’s Principle","aliases":[],"level":9,"school":"Evocação","time":"1 ação ou 1 minuto","range":"10 km","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Bruxo","ritual":false,"concentration":false,"desc":"Você reúne energia eidomântica para rasgar uma fenda no tecido da realidade, expondo-o brevemente a um reino além da cosmologia conhecida. A ruptura é centrada em um ponto à sua escolha a até 10 km, e a inundação de energia eidomântica preenche uma esfera cujo raio você escolhe entre 15 e 150 metros. Cada criatura na área deve realizar um teste de resistência de Constituição, sofrendo 10d10 × 10 de dano de energia em caso de falha ou metade em caso de sucesso. Esse dano não pode ser reduzido por nenhum efeito que não se origine de um artefato, criatura ou magia eidólica, incluindo resistências e imunidades. A esfera não é impedida por matéria física e ignora cobertura, exceto quando a cobertura é o próprio corpo de uma criatura, como um piloto protegido pelo corpo de uma unidade frame.\n\nQualquer criatura ou objeto não eidólico reduzido a 0 pontos de vida é apagado da realidade conhecida: corpo e equipamento desaparecem sem deixar vestígios, exceto objetos feitos de thesite ou de natureza eidólica. A criatura ou objeto deixa de existir em corpo e alma e não pode ser restaurado à vida.\n\nBônus de Astromancia. Se conjurada em um ambiente de gravidade zero, o alcance passa a ser qualquer ponto em sua linha de visão a até 1.000 km, e o raio máximo da esfera é multiplicado por 10.\n\nClassificações Ignoradas. Reduções de dano e diferenças de tamanho entre você e as criaturas afetadas são ignoradas por esta magia.\n\nQueima de Eidomancia Avançada. Se conjurar esta magia como uma ação, realize um teste de resistência de Constituição CD 25. Se conjurá-la ao longo de 1 minuto, a CD é 19. Em caso de falha, você sofre quatro níveis de exaustão e não pode conjurar esta magia novamente. Se isso elevaria sua exaustão a 6, ela é definida como 5 e seus pontos de vida são imediatamente reduzidos a 0. Se a magia for conjurada através de uma unidade frame, uma falha também define a exaustão da unidade em cinco níveis e reduz seus pontos de vida a 0. Uma unidade frame que não seja eidólica morre como resultado e não pode ser revivida.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":204,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia","Eidomancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte. Regra de Eidomancia: ao falhar em um teste de concentração para manter uma magia de Eidomancia, o conjurador pode usar sua reação para rolar outro d20 e usar esse resultado; a Queima de Eidomancia específica permanece descrita no texto da magia."},{"id":"zagalhta-stasis","name":"Estase","originalName":"Stasis","aliases":[],"level":1,"school":"Abjuração","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Druida, Alma Favorecida, Cavaleiro das Pétalas, Patrulheiro, Mago","ritual":false,"concentration":true,"desc":"Você distorce o espaço ao redor de uma criatura a até 9 metros, obrigando-a a realizar um teste de resistência de Força ou Destreza, à escolha dela. O alvo pode escolher falhar voluntariamente e falha automaticamente se estiver incapacitado. Em caso de falha, fica impedido e incapaz de realizar movimento durante a duração da magia. Isso vale tanto para movimento voluntário quanto para movimento involuntário causado por outros efeitos, queda, empurrões e similares. Ficar preso na estase anula qualquer efeito que estivesse movendo o alvo e cancela sua inércia de forma inofensiva.\n\nNo início de cada turno, o alvo pode realizar um teste de Força ou Destreza contra sua CD de magia, escapando em caso de sucesso. Se você deixar de se concentrar ou a magia terminar por outro motivo, o efeito permanece até o início do turno de cada criatura afetada, quando termina para ela.\n\nEscape Alternativo. Uma criatura que se teleporte, seja por deslocamento ou outro efeito, é libertada imediatamente. Se esse teleporte colocar outra criatura no espaço que ela deixou, a nova criatura deve realizar o teste de resistência de Força ou Destreza descrito acima ou ficará presa no lugar dela.\n\nInterferência. Outra criatura pode tentar empurrar um alvo afetado, realizando um teste de Atletismo contra sua CD de magia. Em caso de sucesso, o alvo é libertado. Da mesma forma, se um objeto ou criatura mais de duas categorias de tamanho maior que você entrar ou atravessar o espaço do alvo, ele é empurrado para fora da estase e libertado.\n\nRelatividade. O efeito é relativo a qualquer corpo gravitacional que afete o alvo. Por exemplo, se estiver sobre ou dentro do campo gravitacional de uma nave exolunar em movimento, o alvo e a estase acompanham essa nave.\n\nBônus de Astromancia. Se conjurada em um ambiente de gravidade zero, o alcance é triplicado.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 1º:\n• Você pode conjurar esta magia como uma reação em resposta a uma criatura se mover dentro do alcance.\n• Você pode escolher um alvo adicional dentro do alcance. Como uma ação bônus, pode libertar dos efeitos qualquer quantidade de criaturas afetadas à sua escolha.\n• O alcance dobra.\n• (2 níveis) A magia deixa de exigir concentração, mas você pode encerrar seus efeitos como uma ação bônus.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":204,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-summon-belzer","name":"Invocar Belzer","originalName":"Summon Belzer","aliases":[],"level":2,"school":"Conjuração","time":"1 minuto","range":"9 metros","comp":"V, S, M (um dispositivo mecânico portátil no valor de pelo menos 50 po por belzer, consumido pela magia)","material":"um dispositivo mecânico portátil no valor de pelo menos 50 po por belzer, consumido pela magia","duration":"1 hora","classes":"Druida, Inscritor, Patrulheiro, Bruxo","ritual":true,"concentration":false,"desc":"Para os blocos de estatísticas dos belzers, consulte Lyre’s Guide to Risk & Reward.\n\nVocê invoca uma unidade belzer, escolhendo entre os tipos emboscada, defesa, proteção, deslocamento e mira. O belzer aparece em um espaço desocupado a até 9 metros e permanece por 1 hora, desaparecendo quando a magia termina.\n\nQuando invocado, o belzer possui pontos de vida iguais a 10 × o nível em que esta magia foi conjurada e não pode recuperar pontos de vida.\n\nO belzer obedece aos seus comandos verbais, e você também pode comandá-lo telepaticamente. Ele não realiza ações por conta própria; em seu turno, enquanto ele não estiver incapacitado, você pode usar sua ação bônus para emitir um comando, e o belzer realiza imediatamente a ação ordenada sem precisar de reação. Belzers invocados desta forma podem usar a sua reação para realizar as reações deles.\n\nEnquanto estiver invocado, você pode ouvir e enxergar através dos sentidos do belzer e, quando falar, pode fazê-lo reproduzir suas palavras com sua voz. Belzers invocados desta forma tratam você como se fosse um DGR e um constructo.\n\nBônus de Astromancia. Quando conjurada em um ambiente de gravidade zero, você pode invocar belzers adicionais do mesmo tipo distribuindo entre eles os pontos de vida que o belzer original possuiria, em múltiplos de 15.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode reduzir à metade os pontos de vida atribuídos aos belzers invocados, usando 5 × nível da magia em vez de 10 × nível da magia, para conjurá-la como uma ação.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":205,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-summon-frame-unit","name":"Invocar Unidade Frame","originalName":"Summon Frame Unit","aliases":[],"level":3,"school":"Conjuração","time":"Especial","range":"9 metros","comp":"V, S, M (um objeto de importância pessoal que represente seu vínculo com a unidade frame)","material":"um objeto de importância pessoal que represente seu vínculo com a unidade frame","duration":"Instantânea","classes":"Bardo, Inscritor, Patrulheiro, Mago","ritual":false,"concentration":false,"desc":"Esta magia pode ser usada de três formas, cada uma com um tempo de conjuração diferente.\n\nRegistrar — 1 hora, exige conjuração. Ao longo da conjuração, você alinha uma unidade frame a até 9 metros com você e com o componente material, criando uma sinergia entre vocês. Você só pode estar sincronizado a uma unidade por vez; sincronizar-se a uma nova rompe o vínculo anterior. Você não pode sincronizar uma unidade que já esteja sincronizada a outra criatura viva. Também não pode sincronizar uma unidade cuja diferença de Pegada em relação a você exceda o nível em que esta magia foi conjurada.\n\nInvocar — 1 ação, exige conjuração. Você, ou uma criatura que você permita, pode chamar uma unidade frame com a qual esteja sincronizado e que esteja no mesmo plano, conjurando a magia enquanto segura o componente material. Se a unidade estiver disposta, não estiver incapacitada e possuir pelo menos 1 ponto de vida, você percebe onde ela está e pode fazê-la se teleportar dramaticamente para um espaço desocupado que possa ver a até 9 metros. Se não houver espaço para acomodá-la, ela não pode ser invocada. Se estiver sendo operada, o piloto deve concordar com o teleporte e escolhe se é transportado junto ou deixado para trás. Depois de ser invocada dessa forma, a unidade não pode ser invocada novamente por esta magia durante 1 hora.\n\nEmbarcar — 1 ação bônus. Se a unidade sincronizada estiver a até 30 metros de você, não estiver sendo pilotada, possuir pelo menos 1 ponto de vida e você estiver segurando o componente material, você se teleporta para dentro dela e embarca imediatamente.\n\nBônus de Astromancia. Se invocar a unidade em um ambiente de gravidade zero, você pode optar por embarcar e começar a pilotá-la automaticamente no momento em que ela aparece. Para isso, deve invocá-la em um espaço que se sobreponha ao seu.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":205,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-sunspot-arrow","name":"Flecha de Mancha Solar","originalName":"Sunspot Arrow","aliases":[],"level":3,"school":"Transmutação","time":"1 ação bônus","range":"Toque (1 peça de munição)","comp":"V, S, M (a munição utilizada)","material":"a munição utilizada","duration":"Instantânea","classes":"Paladino, Patrulheiro, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Quando você acerta um ataque com arma à distância que utiliza munição, pode conjurar esta magia para fazer a munição explodir em energia radiante. O alvo e cada criatura a até 6 metros dele realizam um teste de resistência de Destreza, sofrendo 3d8 de dano de fogo e 3d8 de dano radiante em caso de falha, ou nenhum dano em caso de sucesso.\n\nCriaturas que falhem por 5 ou mais ficam cegas por 1 minuto e podem realizar um teste de resistência de Constituição ao fim de cada um de seus turnos, encerrando a condição em caso de sucesso.\n\nO efeito inclui uma explosão de luz solar. Consequentemente, criaturas enfraquecidas pela luz do sol, como vampiros, têm desvantagem no teste de resistência contra esta magia.\n\nBônus de Astromancia. Se conjurada em um ambiente de gravidade zero, criaturas que obtenham sucesso no teste sofrem metade do dano em vez de nenhum.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 3º:\n• Criaturas que falhem no teste ficam cegas independentemente da margem de falha.\n• A área afetada ao redor do alvo inicial aumenta em 3 metros.\n• (2 níveis) Os danos de fogo e radiante aumentam, cada um, em 1d8.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":205,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-surging-scythe","name":"Foice Impetuosa","originalName":"Surging Scythe","aliases":[],"level":2,"school":"Ilusão","time":"1 ação","range":"(hemi)esfera de 4,5 metros de raio","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você cria uma foice de energia psíquica e a varre diante de si, liberando uma onda de loucura. Cada criatura em uma metade contínua de uma esfera de 4,5 metros de raio centrada em você deve realizar um teste de resistência de Inteligência. Em caso de falha, sofre 2d10 de dano psíquico e fica enfurecida, conforme a condição, durante a duração da magia. A CD da condição é sua CD de magia, e os alvos consideram todas as criaturas que não estejam enfurecidas como hostis. Uma criatura enfurecida dessa forma repete o teste ao fim de cada um de seus turnos, encerrando o efeito em caso de sucesso.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode substituir o dano psíquico, inclusive o dano adicional causado por criaturas enfurecidas conforme abaixo, pelo tipo de dano da sua Encarnação.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 2º:\n• O dano aumenta em 1d10.\n• O raio da hemi-esfera aumenta em 4,5 metros.\n• (2 níveis) Criaturas enfurecidas por esta magia não consideram você uma criatura hostil.\n• (2 níveis) Criaturas enfurecidas por esta magia causam 1d8 de dano psíquico adicional em seus ataques com arma.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":206,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-sweeping-glaive","name":"Glaive Varredora","originalName":"Sweeping Glaive","aliases":[],"level":1,"school":"Encantamento","time":"1 ação","range":"Toque (uma arma)","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Patrulheiro, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":true,"desc":"Você toca uma arma e a carrega com energia primordial. Quando essa arma é brandida, projeta uma onda de energia que alcança alvos distantes. Durante a duração da magia, o alcance corpo a corpo da arma aumenta em 4,5 metros, seu dano é considerado mágico e ela causa uma quantidade adicional de d6 do mesmo tipo do dano da arma igual à metade do nível em que a magia foi conjurada, arredondada para cima.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Os dados de dano adicional passam a causar o tipo de dano da sua Encarnação.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 1º:\n• O alcance adicional aumenta em 4,5 metros.\n• Os dados de dano adicional tornam-se d8 (1 nível) ou d10 (3 níveis).\n• (3 níveis) A magia deixa de exigir concentração.\n• (4 níveis) Você pode realizar um ataque com a arma como uma ação bônus.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":206,"category":"Zagalhta's Exolunar Collection","traits":["Arsenal Temível de Ahma"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-sympathetic-gateway","name":"Portal Simpático","originalName":"Sympathetic Gateway","aliases":[],"level":4,"school":"Conjuração","time":"1 minuto","range":"30 metros","comp":"V, M (um mapa estelar, credencial de acesso ou nave exolunar com um motor de portal)","material":"um mapa estelar, credencial de acesso ou nave exolunar com um motor de portal","duration":"Concentração, até 10 minutos","classes":"Clérigo, Alma Favorecida, Inscritor, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Ao conjurar a magia, um portal circular vertical surge no ar, centrado em um ponto que você escolher a até 30 metros. O portal tem 3 metros de raio e conecta-se a uma assinatura de portal registrada pelo componente material, que deve estar no mesmo plano do conjurador. Outro portal se abre no destino registrado, em um local determinado pela assinatura e por sua programação — por exemplo, a assinatura de uma colônia-arca pode fazer naves surgirem na doca, enquanto pessoas sem nave surgem numa área de recepção. O portal permanece durante a duração da magia.\n\nQualquer criatura ou objeto que entre no portal atravessa até o destino e emerge livremente do outro lado.\n\nAssinatura de Portal Persistente. Se uma nave usar esta magia para se teleportar até uma assinatura de portal, deixa no local de partida uma perturbação espacial por 1 minuto. Outra nave ou conjurador pode tentar conjurar esta magia para reabrir o mesmo portal ou seguir seu trajeto. Para isso, o conjurador realiza um teste de habilidade de conjuração com CD igual ao nível em que o Portal Simpático original foi conjurado; outros fatores podem aumentar ou diminuir essa CD. Em caso de sucesso, segue a assinatura conforme descrito. Assinaturas permanentes podem existir pelo universo e funcionar da mesma forma, sem desaparecer.\n\nConjuração Rápida. Se o conjurador pretender transportar apenas a si mesmo ou a nave em que está, pode conjurar esta magia como uma ação. Nesse caso, apenas o conjurador, a nave e todos a bordo são teleportados: nenhum portal permanece, e todos desaparecem e reaparecem no destino como se tivessem atravessado um.\n\nBônus de Nave. Quando esta magia é conjurada através de uma nave com motor de portal, o raio do portal produzido é, no mínimo, grande o bastante para acomodar a nave.","higher":"Quando você conjura esta magia no 5º nível ou superior, o tamanho do portal e o alcance da magia dobram para cada nível acima do 4º. Se conjurada no 6º nível ou superior, a magia deixa de exigir concentração, mas o conjurador pode fechar o portal como uma ação. Se conjurada no 9º nível, pode ser conjurada como uma ação em vez de exigir 1 minuto.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":206,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-thunder-tongue","name":"Língua Trovejante","originalName":"Thunder Tongue","aliases":[],"level":0,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Bardo, Druida, Inscritor","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra de desafio ou uma ordem, magicamente amplificada em força trovejante contra um alvo a até 18 metros. O alvo deve realizar um teste de resistência de Constituição; em caso de falha, sofre 1d10 de dano trovejante. Se falhar por 5 ou mais, também fica caído.\n\nNo 5º nível, esta magia pode escolher duas criaturas dentro do alcance; no 11º nível, três; e no 17º nível, quatro. Você pode escolher a mesma criatura várias vezes, somando o dano de todas as instâncias que a atingiriam e tratando-as como o resultado de um único teste de resistência.","higher":"","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":207,"category":"Zagalhta's Exolunar Collection","traits":[],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-transmission","name":"Transmissão","originalName":"Transmission","aliases":[],"level":4,"school":"Conjuração","time":"1 ação","range":"150 metros","comp":"V","material":"","duration":"Instantânea","classes":"Bardo, Clérigo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Esta magia produz os efeitos de Porta Dimensional.\n\nBônus de Astromancia. Quando conjurada em um ambiente de gravidade zero, a distância de teleporte é triplicada; porém, para se mover além do alcance normal da magia, você deve conseguir ver o destino escolhido.","higher":"Quando você conjura esta magia no 5º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 4º:\n• O alcance dobra.\n• Você pode conjurá-la como uma ação bônus.\n• Pode levar duas criaturas voluntárias adicionais, e a distância máxima que elas podem estar de você para acompanhar o teleporte dobra.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":207,"category":"Zagalhta's Exolunar Collection","traits":["Astromancia"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-vortex-drill","name":"Broca de Vórtice","originalName":"Vortex Drill","aliases":[],"level":3,"school":"Evocação","time":"1 ação","range":"Pessoal (cone de 6 metros)","comp":"S","material":"","duration":"Instantânea","classes":"Alma Favorecida, Paladino, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Você cria um vórtice de energia primordial ao redor de uma arma que esteja segurando e a golpeia para a frente, liberando energia retorcida em um cone de 6 metros. Cada criatura na área realiza um teste de resistência de Destreza. Em caso de falha, sofre como dano de energia o dano normal que a arma causaria em um acerto, mais 2d8 de dano de energia. Em caso de sucesso, sofre metade desse dano.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode fazer todo o dano de energia da magia usar o tipo de dano da sua Encarnação.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 3º:\n• A magia causa 2d8 de dano adicional.\n• O comprimento do cone aumenta em 6 metros.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":207,"category":"Zagalhta's Exolunar Collection","traits":["Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."},{"id":"zagalhta-winged-charge","name":"Investida Alada","originalName":"Winged Charge","aliases":[],"level":3,"school":"Encantamento","time":"1 ação","range":"Pessoal (9 metros)","comp":"S","material":"","duration":"1 rodada","classes":"Alma Favorecida, Paladino, Bruxo, Cavaleiro Dracônico","ritual":false,"concentration":false,"desc":"Um par de asas arcanas cintilantes se abre em suas costas enquanto energia primordial envolve seu corpo. Até o fim do seu próximo turno, você recebe deslocamento de voo igual ao seu deslocamento base e seu deslocamento dobra.\n\nComo parte da conjuração, você pode mergulhar em direção a uma criatura e realizar um único ataque com arma com vantagem contra um alvo a até 9 metros. Em um acerto, causa o dano da arma + 4d10 adicionais do mesmo tipo de dano da arma e termina o ataque em um espaço desocupado adjacente ao alvo.\n\nBônus de Astromancia. Se conjurar esta magia em um ambiente de gravidade zero, também recebe deslocamento de aceleração 0-G igual ao dobro do deslocamento de voo; ele desaparece ao mesmo tempo.\n\nBônus do Cavaleiro Dracônico. Quando conjurada por um Cavaleiro Dracônico, esta magia é tratada como se tivesse sido conjurada dois níveis acima, até o máximo de 9º nível. Você pode usar o tipo de dano da sua Encarnação no lugar do dano adicional da magia.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível acima do 3º:\n• O dano adicional aumenta em 1d10.\n• O alcance da magia dobra.","source":"Somnus Domina — Zagalhta’s Exolunar Collection","sourcePage":207,"category":"Zagalhta's Exolunar Collection","traits":["Legado de Oyd"],"sourceNote":"Versão apresentada no Capítulo 7 — Magias de Zagalhta’s Exolunar Collection, usando a estrutura de regras 5.19 da fonte."}];

window.GRIMORIO_REGISTRY.registerSpellCatalog({id:'zagalhta-spells',sourceId:'zagalhta-exolunar',spells:window.GRIMORIO_ZAGALHTA_SPELLS});

(function linkZagalhtaSpellReprints(){
  const SOURCE = 'Somnus Domina — Zagalhta\'s Exolunar Collection';
  const catalogs = window.GRIMORIO_REGISTRY.getSpellCatalogs();
  let dragonskin = null;
  for (const catalog of catalogs) {
    if (catalog.id === 'zagalhta-spells') continue;
    dragonskin = (catalog.spells || []).find(s => s && s.id === 'lyre-dragonskin') || dragonskin;
  }
  if (dragonskin) {
    dragonskin.otherSources = dragonskin.otherSources || [];
    if (!dragonskin.otherSources.some(x => x && x.title === SOURCE)) dragonskin.otherSources.push({title:SOURCE,pages:'193',note:'Reimpresso no Capítulo 7 — Magias; mantida uma única entrada pesquisável por equivalência mecânica.'});
    const cls = new Set(String(dragonskin.classes || '').split(',').map(x=>x.trim()).filter(Boolean));
    ['Druida','Inscritor','Cavaleiro das Pétalas','Feiticeiro','Bruxo','Mago','Cavaleiro Dracônico'].forEach(x=>cls.add(x));
    dragonskin.classes = Array.from(cls).join(', ');
  }
  window.GRIMORIO_ZAGALHTA_SPELL_REPRINTS = [{id:'lyre-dragonskin',originalName:'Dragonskin',sourcePage:193}];
})();
